  MessageCircle = lucideIcon("MessageCircle"), Globe = lucideIcon("Globe"), RotateCcw = lucideIcon("RotateCcw"),
  Star = lucideIcon("Star"), ArrowLeft = lucideIcon("ArrowLeft"), ArrowRight = lucideIcon("ArrowRight"),
