const UserPlus = lucideIcon("UserPlus"), PartyPopper = lucideIcon("PartyPopper");

/* ==========================================================================
   FIREFLAIR PROTOTYPE v16.16 — FF Team Phase 1 UI (v1.7.1) with FF Staff and
   FF Party open and the booking flow live. FF VIP stays Coming 2027.
   Rebased from the FF Team Phase 1 prototype; set PHASE1.sitesOpen and
   PHASE1.bookingsLive to switch sites and bookings on or off.

   Built from the FireFlair prototype v16.15 and checked against Griffy's
   FF Team frontend + FireFlair backend (GitHub, dev branch, 16 Oct 2026).
   Phase 1 = FF Team as a professional profile and networking platform that
   gets professionals ready for bookings:
     1. Home and website sign-up
     2. Professional profile: create, edit, publish
     3. Profile and card discovery
     4. Networking: invitations, connections, reviews
     5. Register interest: availability, Service Cards, Training, Dream jobs
   Everything else stays in this file for later releases, but is shown as
   Coming Soon and can't start a booking, payment or anything consequential.
   ========================================================================== */
const PHASE1 = {
  name: "FireFlair prototype",
  version: "16.16",
  status: "In development",
  /* The top-left selector, in this order. FF Team, FF Staff and FF Party
     are open in this prototype; FF VIP is Coming 2027. */
  sitesShown: ["team", "staff", "party", "vip"],
  sitesOpen: ["team", "staff", "party"],
  /* Profile sections in Phase 1, in this order. Qualifications above Skills;
     Venues straight after Experience; Work locations as its own section.
     Signature cocktails stay in BASE_CATEGORIES for a later release. */
  profileOrder: ["professions", "qualifications", "skills", "experience", "venues", "locations", "languages", "interests", "media", "reviews"],
  /* FF XP · 2027 runs on the prototype's own XP and tier logic. The only
     way in is the FF coin pop-up: no XP bar, no XP page. */
  xpLive: false,   /* v1.2: XP isn't live in version 1 — the pop-up says Coming 2027 */
  xpBar: false,
  /* Shift requests and booked shifts open with FF Staff and FF Party. The
     Bookings tab shows them as Coming 2027, beside what works now (availability,
     Service Cards, Training and Dream jobs registration). */
  bookingsLive: true,
  /* "Top performers" rankings are leaderboards: not in Phase 1. */
  leaderboards: false,
  /* The desktop "Add FF" button in the top bar is hidden for now. */
  desktopAdd: false,
};
const p1SiteOpen = (key) => PHASE1.sitesOpen.includes(key);
const p1SiteName = (key) => ({ team: "FF Team", staff: "FF Staff", party: "FF Party", vip: "FF VIP" })[key] || "That";
/* " · +10 XP" after a toast, only once XP is live. */
const xpNote = (n) => (PHASE1.xpLive && n ? ` · +${n} XP` : "");

/* --------------------------------------------------------------------------
   LANGUAGES — the master list from the backend
   (FireFlair-Backend scripts/seedLanguages.js: "FireFlair Profile Language
   Flags Specification" v1.1, 52 languages, in the spec's order), with real
   flag images instead of flag emoji. Windows shows flag emoji as two bare
   letters ("FR"), which Griffy's frontend already fixed with SVG flags; this
   is the same fix for the prototype. [iso639, name, flag key]
   -------------------------------------------------------------------------- */
const LANGUAGE_MASTER = [
  ["fr", "French", "FR"], ["it", "Italian", "IT"], ["es", "Spanish", "ES"], ["en", "English", "GB"],
  ["de", "German", "DE"], ["pt", "Portuguese", "PT"], ["nl", "Dutch", "NL"], ["el", "Greek", "GR"],
  ["cy", "Welsh", "gbwls"], ["gd", "Scottish Gaelic", "gbsct"], ["sco", "Scots", "gbsct"], ["ga", "Irish", "IE"],
  ["kw", "Cornish", "GB"], ["bfi", "British Sign Language", "sign_language"],
  ["pl", "Polish", "PL"], ["ro", "Romanian", "RO"], ["lt", "Lithuanian", "LT"], ["bg", "Bulgarian", "BG"],
  ["hu", "Hungarian", "HU"], ["cs", "Czech", "CZ"], ["sk", "Slovak", "SK"], ["ru", "Russian", "RU"],
  ["uk", "Ukrainian", "UA"], ["sq", "Albanian", "AL"], ["hr", "Croatian", "HR"],
  ["ar", "Arabic", "SA"], ["tr", "Turkish", "TR"], ["fa", "Persian (Farsi)", "IR"], ["ps", "Pashto", "AF"], ["ku", "Kurdish", "globe"],
  ["hi", "Hindi", "IN"], ["pa", "Punjabi", "IN"], ["gu", "Gujarati", "IN"], ["ta", "Tamil", "IN"], ["te", "Telugu", "IN"],
  ["ml", "Malayalam", "IN"], ["mr", "Marathi", "IN"], ["bn", "Bengali", "BD"], ["ur", "Urdu", "PK"], ["ne", "Nepali", "NP"], ["si", "Sinhala", "LK"],
  ["zh", "Mandarin Chinese", "CN"], ["yue", "Cantonese", "HK"], ["ja", "Japanese", "JP"], ["ko", "Korean", "KR"],
  ["vi", "Vietnamese", "VN"], ["tl", "Tagalog (Filipino)", "PH"],
  ["so", "Somali", "SO"], ["sw", "Swahili", "KE"], ["yo", "Yoruba", "NG"], ["am", "Amharic", "ET"], ["ti", "Tigrinya", "ER"],
].map(([iso, name, flag]) => ({ iso, name, flag }));
/* Other ways people write the same language (CVs, typing). */
const LANGUAGE_ALIASES = {
  mandarin: "zh", chinese: "zh", farsi: "fa", persian: "fa", filipino: "tl", tagalog: "tl",
  bsl: "bfi", "sign language": "bfi", gaelic: "gd", "scots gaelic": "gd", castilian: "es",
  "brazilian portuguese": "pt", flemish: "nl", "english (uk)": "en", "british english": "en",
};
/* Flag pictures (24px tall, from the open-source Noto emoji set). */
const LANG_FLAG_IMG = {"FR":"data:image/webp;base64,…(1 KB)","IT":"data:image/webp;base64,…(1 KB)","ES":"data:image/webp;base64,…(1 KB)","GB":"data:image/webp;base64,…(2 KB)","DE":"data:image/webp;base64,…(1 KB)","PT":"data:image/webp;base64,…(1 KB)","NL":"data:image/webp;base64,…(1 KB)","GR":"data:image/webp;base64,…(2 KB)","IE":"data:image/webp;base64,…(1 KB)","PL":"data:image/webp;base64,…(1 KB)","RO":"data:image/webp;base64,…(1 KB)","LT":"data:image/webp;base64,…(1 KB)","BG":"data:image/webp;base64,…(1 KB)","HU":"data:image/webp;base64,…(1 KB)","CZ":"data:image/webp;base64,…(1 KB)","SK":"data:image/webp;base64,…(1 KB)","RU":"data:image/webp;base64,…(1 KB)","UA":"data:image/webp;base64,…(1 KB)","AL":"data:image/webp;base64,…(1 KB)","HR":"data:image/webp;base64,…(1 KB)","SA":"data:image/webp;base64,…(1 KB)","TR":"data:image/webp;base64,…(1 KB)","IR":"data:image/webp;base64,…(1 KB)","AF":"data:image/webp;base64,…(1 KB)","IN":"data:image/webp;base64,…(1 KB)","BD":"data:image/webp;base64,…(1 KB)","PK":"data:image/webp;base64,…(1 KB)","NP":"data:image/webp;base64,…(2 KB)","LK":"data:image/webp;base64,…(2 KB)","CN":"data:image/webp;base64,…(1 KB)","HK":"data:image/webp;base64,…(1 KB)","JP":"data:image/webp;base64,…(1 KB)","KR":"data:image/webp;base64,…(1 KB)","VN":"data:image/webp;base64,…(1 KB)","PH":"data:image/webp;base64,…(1 KB)","SO":"data:image/webp;base64,…(1 KB)","KE":"data:image/webp;base64,…(1 KB)","NG":"data:image/webp;base64,…(1 KB)","ET":"data:image/webp;base64,…(1 KB)","ER":"data:image/webp;base64,…(1 KB)","gbwls":"data:image/webp;base64,…(2 KB)","gbsct":"data:image/webp;base64,…(2 KB)","globe":"data:image/webp;base64,…(2 KB)","sign_language":"data:image/webp;base64,…(2 KB)"};
function languageInfo(name) {
  const k = String(name || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (!k) return null;
  const iso = LANGUAGE_ALIASES[k];
  return LANGUAGE_MASTER.find(l => l.name.toLowerCase() === k || l.iso === k || (iso && l.iso === iso)
    || l.name.toLowerCase().replace(/\s*\(.*\)$/, "") === k) || null;
}
/* A language's flag, sized to the text around it. A language that isn't on
   the master list gets the globe (spec §4.3). */
function LangFlag({ lang, style }) {
  const info = languageInfo(lang);
  const src = LANG_FLAG_IMG[info ? info.flag : "globe"] || LANG_FLAG_IMG.globe;
  return <img className="ff-langflag" src={src} alt="" aria-hidden="true" style={style} />;
}


