/* NETWORK — the bartending network, for everyone. Signed-out visitors see
   the same people a member does; joining happens on Home and Profile. */
function NetworkScreen({ guest = false }) {
  const { state, dispatch } = useStore();
  const [inviting, setInviting] = useState(false);
  const [reviewing, setReviewing] = useState(null);
  useEffect(() => { const h = () => setInviting(true); window.addEventListener("ff-invite", h); return () => window.removeEventListener("ff-invite", h); }, []);
  const q = state.netQuery || "";
  const setQ = (v) => dispatch({ type: "NET_QUERY", q: v });
  const mine = guest ? { inviter: null, list: [] } : myNetwork(state, adminPeople17(state, state.directory));
  const connected = mine.list;
  const view = (p) => { dispatch({ type: "VIEW", id: p.id }); window.scrollTo(0, 0); };
  const join = () => { dispatch({ type: "ROLE", role: "team" }); dispatch({ type: "TAB", tab: "profile", route: "home" }); window.scrollTo(0, 0); };

  return (
    <div>
      <div className="ff-eyebrow">{guest ? "FireFlair" : "FF Team"}</div>
      <div style={{ display: "flex", alignItems: "flex-end", gap: 10, marginTop: 4 }}>
        <h1 className="ff-h1" style={{ flex: 1 }}>Network</h1>
        {!guest && ph17(state) >= 2 && <Btn variant="sm" onClick={() => setInviting(true)}><Send size={12} /> Invite</Btn>}
      </div>

      <FFAI query={q} onQuery={setQ} title="Search the network"
        placeholder="Search the network. Describe who you're looking for." />

      {guest && !q && (
        <div className="ff-pendingnote" style={{ marginTop: 6 }}>
          <span>{ph17(state) >= 2 ? "Join FF Team to build your own network. Whoever invites you is added to it automatically." : "Join FF Team to create your own Profile Card."}</span>
          <Btn variant="sm primary" onClick={join}><User size={12} /> Create your Profile Card</Btn>
        </div>
      )}

      {!q && ph17(state) >= 2 && mine.inviter && <InvitedByBanner person={mine.inviter} onReview={() => setReviewing(mine.inviter)} />}

      {!q && !guest && ph17(state) >= 2 && (
        <section style={{ marginTop: 20 }}>
          <SectionHead icon={<Check size={15} color="var(--gold-dk)" strokeWidth={1.6} />} title="Your network" count={connected.length} />
          <HScroll label="Your network">
            {connected.map(p => (
              <div key={p.id} className="ff-nettile">
                <NetworkTile person={p} invited={!!(mine.inviter && mine.inviter.id === p.id)} onClick={() => view(p)} />
                <button type="button" className="ff-btn sm ghost" onClick={() => setReviewing(p)}><Award size={12} /> Review</button>
              </div>
            ))}
            <button className="ff-card ff-portrait ff-addtile" style={{ width: CARD_W.player }} onClick={() => setInviting(true)}>
              <span style={{ textAlign: "center" }}><UserPlus size={20} color="var(--gold-dk)" />
                <span className="ff-label" style={{ display: "block", marginTop: 6 }}>Invite</span></span>
            </button>
          </HScroll>
        </section>
      )}
      {!q && !guest && ph17(state) >= 2 && <SentInvitations />}

      <NetBrowse17 query={q} onPick={view} after={<><NetMap11 />{!q && <TopStaff11 />}</>} />
      {!q && (<>
        {PHASE1.leaderboards && <Rankings />}
        <Divider />
      </>)}
      <V101.BusinessSupport19 />
      {!guest && <InviteSheet open={inviting} onClose={() => setInviting(false)} />}
      <ReviewSheet open={!!reviewing} person={reviewing} onClose={() => setReviewing(null)} />
    </div>
  );
}

/* --- FF Team: home, bookings, profile ------------------------------------ */




function BookingSheet({ engagement, onClose }) {
  const { state, dispatch } = useStore();
  if (!engagement) return null;
  const shift = state.shifts.find(s2 => s2.id === engagement.shiftId);
  const event = state.events.find(v => v.id === shift?.eventId);
  const e = engagement;
  if (!shift) return null;
  const act = (st) => { dispatch({ type: "ENG_STATE", id: e.id, state: st }); onClose(); };

  return (
    <Sheet open onClose={onClose} title={shift.role}>
      <ShiftCard shift={shift} event={event} footer={
        <div>
          <div style={{ marginBottom: 10 }}><Pill tone={ENG_TONE[e.state]}><span className="ff-dot" /> {ENG_LABEL[e.state]}</Pill></div>
          {["requested", "discuss", "available", "withdrawn", "not_selected", "cancelled_pro"].includes(e.state) && <ProOffer17 e={e} shift={shift} onDone={onClose} />}
          {e.state === "requested" && e.expiresAt && <p className="ff-body ff-muted" style={{ margin: "8px 0 0", fontSize: 12 }}>{timeLeft(e.expiresAt)}</p>}
          {e.state === "expired" && <p className="ff-body ff-muted" style={{ margin: 0 }}>This request expired without a reply.</p>}
          {e.state === "confirmed" && (
            <div>
              <p className="ff-body" style={{ margin: "0 0 10px" }}>You are booked.</p>
              <ProOffer17 e={e} shift={shift} onDone={onClose} />
              <WalletButton kind="booking" wide dark={false} payload={{ shiftId: shift.id, role: shift.role, date: shift.date, venue: shift.venue }} />
            </div>
          )}
          {e.state === "completed" && <Btn variant="primary wide" onClick={() => act("signed_off")}><PenLine size={14} /> Sign off this shift</Btn>}
          {e.state === "signed_off" && <p className="ff-body ff-muted" style={{ margin: 0 }}>Signed off. The hirer pays you directly, as agreed on the Service Card.</p>}
          {e.state === "paid" && <p className="ff-body" style={{ margin: 0 }}>This shift is closed.</p>}
        </div>
      } />
    </Sheet>
  );
}

/* BOOKINGS (FF Team) — one page, three sections: booked shifts, FF Party
   service cards (coming in 2027), availability cards. Replies happen here. */
/* ==========================================================================
   BOOKINGS — full-size poster cards. One PosterCard frame for every kind
   (booking, FF Party service); the tone sets the surface and metal.
   ========================================================================== */
const POSTER_TONES = {
  dark:   { cls: "dark",   accent: "#D9B552", ribbon: "Booking Card" },
  ivory:  { cls: "ivory",  accent: "#9A7322" },
  bronze: { cls: "dark metal", accent: "#D49A62", edge: "bronze" },
  silver: { cls: "dark metal", accent: "#D6DAE0", edge: "silver" },
  gold:   { cls: "dark metal", accent: "#E8C75E", edge: "gold" },
  white:  { cls: "ivory white", accent: "#9A7322" },
};

function PosterCard({ tone = "dark", ribbon, eyebrow, title, subtitle, tagline, rows = [], footer, onClick }) {
  const t = POSTER_TONES[tone] || POSTER_TONES.dark;
  return (
    <article className={`ff-poster ${t.cls}`} style={{ "--pc-accent": t.accent, ...(t.edge ? { "--pc-edge": metalEdge(t.edge) } : {}) }}>
      <div className="ff-poster-ribbon"><Sparkles size={11} /> {ribbon}</div>
      <span className="ff-poster-coin"><Coin size={44} tier={t.edge || "gold"} /></span>
      <div className="ff-poster-head">
        {eyebrow && <div className="ff-poster-eyebrow">✦ {eyebrow} ✦</div>}
        <h3 className="ff-poster-title">{title}</h3>
        {subtitle && <div className="ff-poster-sub">{subtitle}</div>}
        {tagline && <p className="ff-poster-tag">{tagline}</p>}
      </div>
      <div className="ff-poster-rows">
        {rows.filter(Boolean).map((r, i) => (
          <div key={i} className="ff-poster-row">
            <span className="ff-poster-medal">{r.icon}</span>
            <span style={{ minWidth: 0 }}>
              <span className="ff-poster-label">{r.label}</span>
              <span className="ff-poster-value">{r.value}</span>
              {r.sub && <span className="ff-poster-small">{r.sub}</span>}
            </span>
          </div>
        ))}
      </div>
      {footer && <div className="ff-poster-foot">{footer}</div>}
      {onClick && <button type="button" className="ff-poster-hit" onClick={onClick} aria-label={`Open ${title}`} />}
    </article>
  );
}

const PAST_STATES = ["completed", "signed_off", "paid"];

/* Peak dates: the busiest nights of the year. Saying yes puts the person
   first in line for shifts on the dates they pick. */
const isoDays = (from, to) => { const out = []; for (let d = new Date(from + "T12:00:00"); d <= new Date(to + "T12:00:00"); d.setDate(d.getDate() + 1)) out.push(d.toISOString().slice(0, 10)); return out; };
const PEAK_DATES = [
  { key: "halloween", icon: "🎃", q: "Are you available for Halloween bookings?", dates: isoDays("2026-10-29", "2026-11-01") },
  { key: "christmas", icon: "🎄", q: "Are you available for Christmas bookings?", dates: isoDays("2026-12-01", "2026-12-24"), grid: true },
  { key: "nye", icon: "🥂", q: "Are you available on New Year's Eve?", dates: ["2026-12-31", "2027-01-01"] },
];
const WEEKDAY = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const chipDate = (iso) => { const d = new Date(iso + "T12:00:00"); return { wd: WEEKDAY[d.getDay()], day: d.getDate(), mon: MONTHS[d.getMonth()].slice(0, 3) }; };

function PeakAvailability() {
  const { state, dispatch } = useStore();
  const peak = state.profile.peak || {};
  const set = (key, patch) => dispatch({ type: "PROFILE", patch: { peak: { ...peak, [key]: { ...(peak[key] || {}), ...patch } } } });
  return (
    <div style={{ display: "grid", gap: 12 }}>
      {PEAK_DATES.map(pk => {
        const cur = peak[pk.key] || {};
        const picked = cur.dates || [];
        const toggle = (iso) => set(pk.key, { dates: picked.includes(iso) ? picked.filter(x => x !== iso) : [...picked, iso].sort() });
        return (
          <div key={pk.key} className="ff-panel">
            <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
              <span style={{ fontSize: 24 }} aria-hidden="true">{pk.icon}</span>
              <span style={{ flex: 1, minWidth: 200, fontWeight: 700, fontSize: 15.5, color: "#16130F" }}>{pk.q}</span>
              <span className="ff-seg" role="group" aria-label={pk.q}>
                <button type="button" aria-pressed={cur.answer === "yes"} onClick={() => set(pk.key, { answer: "yes", dates: picked.length ? picked : pk.dates.slice() })}>Yes</button>
                <button type="button" aria-pressed={cur.answer === "no"} onClick={() => set(pk.key, { answer: "no", dates: [] })}>No</button>
              </span>
            </div>
            {cur.answer === "yes" && (<>
              <p className="ff-body" style={{ margin: "12px 0 8px", fontSize: 13 }}>Tap the dates you're free — {picked.length} selected.</p>
              <div className={pk.grid ? "ff-dategrid" : ""} style={pk.grid ? undefined : { display: "flex", gap: 8, flexWrap: "wrap" }}>
                {pk.dates.map(iso => { const c = chipDate(iso); const on = picked.includes(iso); return (
                  <button key={iso} type="button" className={`ff-datechip${on ? " on" : ""}`} aria-pressed={on} onClick={() => toggle(iso)}>
                    <small>{c.wd}</small><b>{c.day}</b><small>{c.mon}</small>
                  </button>
                ); })}
              </div>
            </>)}
            {cur.answer === "yes" && picked.length > 0 && (
              <p className="ff-body" style={{ margin: "10px 0 0", fontSize: 12.5, color: "#5C1220", fontWeight: 600 }}><Star size={12} fill="currentColor" /> You're on the priority list for these dates.</p>
            )}
          </div>
        );
      })}
    </div>
  );
}


