    highball: <><path d="M7 3.5h10l-1 16.8a.8.8 0 0 1-.8.7H8.8a.8.8 0 0 1-.8-.7L7 3.5z" {...P} /><path d="M7.4 9.5h9.2" {...P} /></>,
