const PC_AREAS = Object.fromEntries(PC_TABLE.split("\n").map(l => {
  const [k, t, n, f] = l.split("|");
  return [k, { t, n: n.split(","), f: PC_PRESETS[f] }];
}));
function parsePostcode(raw) {
  const s = String(raw || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  const full = s.match(/^([A-Z]{1,2}\d[A-Z\d]?)(\d[A-Z]{2})$/);
  const out = full ? full[1] : (/^[A-Z]{1,2}\d[A-Z\d]?$/.test(s) ? s : null);
  if (!out) return { ok: false };
  return { ok: true, outward: out, display: full ? `${full[1]} ${full[2]}` : out, partial: !full };
}
function postcodeArea(p) {
  const letters = (p.outward.match(/^[A-Z]+/) || [""])[0];
  return PC_AREAS[p.outward] || PC_AREAS[letters] || null;
}

function p1PrimaryLocationReducer(s, a) {
  let list = rankAll(recsOf(s.profile, "locations"));
  let rec = list.find(r => r.name.toLowerCase() === a.name.toLowerCase());
  if (!rec) { rec = { ...makeRecord("locations", a.name), rank: "tertiary" }; list = [...list, rec]; }
  rec = { ...rec, hidden: false, proposed: false };
  list = list.map(r => r.id === rec.id ? rec : r);
  const olds = list.filter(r => r.id !== rec.id && !r.hidden && !r.proposed && r.rank === "primary");
  list = moveRecord(list, rec.id, "primary", 0).list;
  olds.forEach(o => { list = moveRecord(list, o.id, "secondary", 0).list; });
  const next = withRecords(s, "locations", list);
  return a.postcode ? { ...next, workPostcode: { code: a.postcode, town: a.name, at: Date.now() } } : next;
}

function WorkLocationsBox({ items, onAdd }) {
  const { state, dispatch } = useStore();
  const saved = state.workPostcode;
  const [pc, setPc] = useState("");
  const [err, setErr] = useState("");
  const [look, setLook] = useState(null);       // { p, town, groups: [{key,label,names}] }
  const [off, setOff] = useState({});           // suggestions switched off
  const [changing, setChanging] = useState(false);
  const shown = items.filter(r => !r.hidden && !r.proposed);
  const names = shown.map(r => r.name);
  const prime = withRanks(items).find(e => e.rank === "primary" && !e.r.hidden && !e.r.proposed);
  const primaryName = prime ? prime.r.name : "";

  const find = () => {
    const p = parsePostcode(pc);
    if (!p.ok) { setErr("That doesn’t look like a UK postcode — try something like HP4 1BS."); return; }
    setErr("");
    const area = postcodeArea(p);
    const town = area ? area.t : "";
    setOff({});
    setLook({
      p, town, known: !!area,
      groups: area ? [{ key: "near", label: "Large towns nearby", names: area.n }, { key: "far", label: "Further afield", names: area.f }] : [],
    });
  };
  const apply = () => {
    const town = (look.town || "").trim().replace(/\s+/g, " ");
    if (!town) { setErr("Add the town or area your postcode is in."); return; }
    const chosen = look.groups.flatMap(g => g.names).filter(n => !off[n] && n.toLowerCase() !== town.toLowerCase());
    dispatch({ type: "P1_SET_PRIMARY_LOC", name: town, postcode: look.p.display });
    const fresh = chosen.filter(n => !names.some(x => x.toLowerCase() === n.toLowerCase()));
    if (fresh.length) dispatch({ type: "RECORDS_MERGE", byCategory: { locations: fresh.map(n => makeRecord("locations", n)) } });
    dispatch({ type: "TOAST", toast: `${town} is your primary location${fresh.length ? ` · ${fresh.length} more added` : ""}` });
    setLook(null); setPc(""); setChanging(false);
  };
  const choosing = !!look;
  const showForm = !saved || changing || choosing;
  const count = look ? look.groups.flatMap(g => g.names).filter(n => !off[n]).length : 0;

  return (
    <div className="ff-frame ff-goldpick ff-wlbox" style={{ padding: 14, marginTop: 14 }}>
      <div className="ff-label" style={{ marginBottom: 8 }}>Where you work</div>
      <WorkLocationsGuide count={shown.length} bare />

      <div className="ff-wlbox-ai">
        <Coin size={22} tier="gold" />
        <span>Enter your postcode. It stays private; only your area is shown.</span>
      </div>

      {!showForm && (
        <div className="ff-wlbox-saved">
          <div><MapPin size={14} strokeWidth={1.9} /> <b>Primary location:</b> {primaryName || saved.town}</div>
          <div className="sub">Postcode {saved.code.split(" ")[0]} ••• · kept private · used for travel distances</div>
          <div className="row">
            <button type="button" className="ff-btn sm ghost" onClick={() => setChanging(true)}><Pencil size={12} /> Change postcode</button>
            {onAdd && <button type="button" className="ff-btn sm ghost" onClick={onAdd}><Plus size={12} /> Add more locations</button>}
          </div>
        </div>
      )}

      {showForm && !choosing && (
        <div>
          <label className="ff-label" htmlFor="ff-wl-pc" style={{ display: "block", margin: "10px 0 6px" }}>Your postcode</label>
          <div className="ff-wlbox-pc">
            <input id="ff-wl-pc" className="ff-input" value={pc} autoComplete="postal-code" spellCheck={false} placeholder="e.g. HP4 1BS"
              aria-label="Your postcode" onChange={(e) => { setPc(e.target.value.toUpperCase().slice(0, 9)); setErr(""); }}
              onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); find(); } }} />
            <button type="button" className="ff-btn primary" onClick={find} disabled={!pc.trim()}>Find my areas</button>
          </div>
          {err && <p className="ff-wlbox-err" role="alert">{err}</p>}
          {!saved && !primaryName && <p className="ff-body ff-muted" style={{ fontSize: 11.5, margin: "6px 0 0" }}>Prefer not to? Add locations yourself with Add location below — your first one becomes your primary.</p>}
          {changing && <button type="button" className="ff-btn sm ghost" style={{ marginTop: 8 }} onClick={() => { setChanging(false); setErr(""); }}>Cancel</button>}
        </div>
      )}

      {choosing && (
        <div className="ff-wlbox-result">
          <div className="ff-label" style={{ margin: "10px 0 6px" }}>Primary location · used for travel distances</div>
          <input className="ff-input" value={look.town} aria-label="Primary location" placeholder="Your town or area"
            onChange={(e) => setLook({ ...look, town: e.target.value })} />
          {!look.known && <p className="ff-body ff-muted" style={{ fontSize: 11.5, margin: "6px 0 0" }}>We don’t know that postcode area here — type your town above and add other places afterwards.</p>}
          {look.groups.map(g => (
            <div key={g.key}>
              <div className="ff-label" style={{ margin: "12px 0 6px" }}>{g.label}</div>
              <div role="list" aria-label={g.label}>
                {g.names.filter(n => n.toLowerCase() !== look.town.toLowerCase()).map(n => {
                  const on = !off[n];
                  return (
                    <button key={n} type="button" role="listitem" aria-pressed={on} className="ff-chip" onClick={() => setOff({ ...off, [n]: on })}
                      style={on ? { background: "#5C1220", borderColor: "#5C1220", color: "#F6E7B4" } : undefined}>{on ? "✓ " : "+ "}{n}</button>
                  );
                })}
              </div>
            </div>
          ))}
          {err && <p className="ff-wlbox-err" role="alert">{err}</p>}
          <div className="ff-wlbox-actions">
            <button type="button" className="ff-btn primary" onClick={apply}><Check size={13} /> Use {count ? `these ${count + 1}` : "this"} location{count ? "s" : ""}</button>
            <button type="button" className="ff-btn ghost" onClick={() => { setLook(null); setErr(""); }}>Back</button>
          </div>
          <p className="ff-body ff-muted" style={{ fontSize: 11.5, margin: "8px 0 0" }}>You can add as many more as you like afterwards.</p>
        </div>
      )}
    </div>
  );
}

