        /* v17.3.39: each viewer saves to their own private record (data/users/<id>/fireflair). The old shared
           "fireflair/state" document let viewers overwrite, and see, each other's data. No identity: nothing is saved. */
        const user = await (window.claude.use ? window.claude.use("user") : Promise.resolve(null));
        const me = user ? await user.me() : null;
        if (!me || !me.id || cancelled) return;
