          PERSIST_KEYS.forEach(k => { if (saved[k] !== undefined) patch[k] = saved[k]; });
          if (Array.isArray(patch.joinedPeople) && patch.joinedPeople.length) patch.directory = [...DIRECTORY, ...patch.joinedPeople.filter(p => !DIRECTORY.some(d => d.id === p.id))];
          /* Bookings saved before FF Staff 1.0 used multi-person shifts. Start
             those viewers on the new one-person Service Card demo data instead. */
