  const no = () => { go("unavailable"); dispatch({ type: "TOAST", toast: "Declined. The host has been told" }); onDone && onDone(); };
  const send = () => { if (!txt.trim()) return; go("discuss", txt.trim()); setTxt(""); setAsk(false); };
