/* Training, Dream jobs and FF rewards cards: tap one and it turns over to its description. Both sites. */
function FlipChoice17({ kind, title, img, note, on, onClick }) {
  const [back, setBack] = useState(false);
  const key = (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setBack(b => !b); } };
  const tick = (
    <button type="button" className="tick" aria-pressed={on} onClick={(e) => { e.stopPropagation(); onClick(); }}>
      {on ? <><S17I.Check size={13} strokeWidth={2.6} /> Interested</> : <><S17I.Plus size={13} /> I'm interested</>}
    </button>
  );
  return (
    <div className={`ff-fc17${back ? " back" : ""}`}>
      <div className="fi">
        <div className="ff-shine-img fr" role="button" tabIndex={back ? -1 : 0} aria-pressed={on} aria-label={`${title}: turn over`} onClick={() => setBack(true)} onKeyDown={key}>
          {img ? <img src={img} alt="" loading="eager" draggable="false" /> : <HomeScene kind="bar" />}
          <span className="shade" aria-hidden="true" />
          <span className="k">{kind}</span>
          <span className="tx"><span className="t">{title}</span>
          {note && <span className="d">{note}</span>}</span>
          {tick}
          {on && <span className="chk" aria-hidden="true"><S17I.Check size={13} strokeWidth={3} /></span>}
        </div>
        <div className="bk" role="button" tabIndex={back ? 0 : -1} aria-label={`${title}: turn back`} onClick={() => setBack(false)} onKeyDown={key}>
          <b className="bt">{title}</b>
          <p>{note}</p>
          {tick}
        </div>
      </div>
    </div>
  );
}

/* ---- v17.3.37: FireFlair package cards, the size of a featured company card, and the pop-up that books one ---- */
const PKICON17 = { bar: S17I.Martini, ent: S17I.Music, svc: S17I.Camera, food: S17I.UtensilsCrossed };
function PkgCard17({ svc, n, noun, match, on, onToggle, onInfo }) {
  const Ic = PKICON17[svc.cat] || S17I.Sparkles;
  return (
    <div className={`ff-pk17w${on ? " sel" : ""}`} data-pk17={svc.id} data-pk17-alt={svc.title === "BYOB" ? "byob" : ""}>
      <button type="button" className={`ff-lst ff-pk17 ${svc.tone || ""}${match ? " match" : ""}`} onClick={onToggle} aria-pressed={!!on} aria-label={`${svc.title}: ${on ? "selected" : "select"}`}>
        <span className="ph" style={svc.img ? { backgroundImage: `linear-gradient(rgba(10,8,8,.12),rgba(10,8,8,.55)), url(${svc.img})`, backgroundSize: "cover", backgroundPosition: "center 20%" } : undefined}>
          <span className="pl">{lvl17(svc.level)}</span>
          <span className="cn"><Coin size={30} tier="gold" /></span>
          <span className="ic"><Ic size={34} strokeWidth={1.4} /></span>
          {svc.price && !svc.noPrice && <span className="pr">{svc.price}</span>}
        </span>
        <span className="tx">
          <b>{svc.title}</b>
          <small className="tg">{svc.tagline}</small>
          {svc.includes && <span className="ft"><S17I.Sparkles size={12} /> {svc.includes}</span>}
          {svc.ideal && <span className="ft"><S17I.Star size={12} /> {svc.ideal}</span>}
          {svc.time && <span className="ft"><S17I.Clock size={12} /> {svc.time}</span>}
          {shop17(svc) && <span className="ft"><S17I.ShoppingBasket size={12} /> Shopping list for your cocktails</span>}
          <span className="ft rec"><S17I.Users size={12} /> Best for {recOf17(svc.bands)}</span>
          <span className="by">{svc.by ? svc.by : svc.mine ? "Your package" : n > 0 ? `${n} ${noun} to choose from` : "FF Party"}</span>
          <span className="go">{on ? <><S17I.Check size={13} strokeWidth={2.6} /> Selected</> : <>Select</>}</span>
        </span>
      </button>
      <button type="button" className="inf" aria-label={`${svc.title}: details`} onClick={onInfo}><S17I.Info size={16} strokeWidth={2} /></button>
    </div>
  );
}
function PkgSheet17({ svc, qual, onClose }) {
  const { state, dispatch } = useStore();
  const bk = bkOf17(state);
  const on = bk.pk.includes(svc.id);
  const Ic = PKICON17[svc.cat] || S17I.Sparkles;
  const feats = [...(svc.features || String(svc.includes || "").split(/,\s*|\s+and\s+/).filter(Boolean).map(x => x.charAt(0).toUpperCase() + x.slice(1))), ...(shop17(svc) ? ["We provide a shopping list for all of your selected cocktails"] : [])];
  const sf = state.svFav17 || [], inF = sf.includes(svc.id);
  const toggleF = () => { dispatch({ type: "V11_SET", patch: { svFav17: inF ? sf.filter(x => x !== svc.id) : [...sf, svc.id] } }); if (!inF) dispatch({ type: "TOAST", toast: `${svc.title} added to your favourites` }); };
  const toggle = () => {
    dispatch({ type: "V11_SET", patch: { bk17: { ...bk, pk: pkFlip17(bk.pk, svc.id) } } });
    if (!on) dispatch({ type: "TOAST", toast: `${svc.title} added to your basket` });
    onClose();
  };
  return (
    <Sheet open onClose={onClose} title={svc.title}>
      <div className={`ff-pks17 ${svc.tone || ""}`}>
        <div className="hd">
          <span className="ic"><Ic size={30} strokeWidth={1.4} /></span>
          <span className="t"><small>{[lvl17(svc.level), svc.by || "FF Party"].filter(Boolean).join(" · ")}</small><b>{svc.title}</b></span>
          {svc.price && !svc.noPrice && <span className="pr">{svc.price}</span>}
        </div>
        <p className="tg">{svc.tagline}</p>
        <ul className="fx">{feats.map(f => <li key={f}><S17I.Check size={14} strokeWidth={2.6} /> {f}</li>)}</ul>
        <div className="mt">
          <span><S17I.Users size={13} /> Best for {recOf17(svc.bands)}</span>
          {svc.ideal && <span><S17I.Star size={13} /> {svc.ideal}</span>}
          {svc.time && <span><S17I.Clock size={13} /> {svc.time}</span>}
          {qual && <span className={`q ${qual}`}>{(QUALITY17.find(o => o.k === qual) || {}).label} preferred</span>}
        </div>
        {svc.id === "svc_full" && <div className="ff-br17-qual" role="group" aria-label="Preferred quality">
          {QUALITY17.map(o => <button key={o.k} type="button" className={`${o.k}${qual === o.k ? " on" : ""}`} aria-pressed={qual === o.k} onClick={() => dispatch({ type: "V11_SET", patch: { br17: { ...(state.br17 || {}), q: qual === o.k ? "" : o.k } } })}><b>{o.label}</b></button>)}
        </div>}
        <button type="button" className="ff-pks17-go" aria-pressed={on} onClick={toggle}>{on ? <><S17I.Check size={16} strokeWidth={2.6} /> In your basket</> : <><S17I.Plus size={16} /> Add to basket</>}</button>
        <button type="button" className={`ff-pks17-fav${inF ? " on" : ""}`} aria-pressed={inF} onClick={toggleF}><S17I.Heart size={16} fill={inF ? "currentColor" : "none"} /> {inF ? "In your favourites" : "Add to favourites"}</button>
      </div>
    </Sheet>
  );
}

/* ---- v17.3.57: Confirm your booking. The basket in two layers, the Event Card, the invoice and the confirm spin button. ---- */
function HostDrop17() {
  const { state, dispatch } = useStore();
  const c = state.company || {};
  const [open, setOpen] = useState(false);
  const save = () => { dispatch({ type: "COMPANY_SAVE", company: { cardSavedAt: Date.now(), joinedAt: c.joinedAt || Date.now() } }); dispatch({ type: "TOAST", toast: "Host card saved" }); setOpen(false); };
  return (
    <div className="ff-hc17">
      <button type="button" className="h" aria-expanded={open} onClick={() => setOpen(v => !v)}>
        <span className="cn"><Coin size={34} tier="gold" /></span>
        <span className="t"><b>Host info</b><small>We recommend you create a Host Card to share your details.</small></span>
        <S17I.ChevronDown size={18} className="cv" />
      </button>
      {open && <div className="b"><PartyCard11 edit /><ConfirmSpin17 lines={["Save"]} label="Save host card" onClick={save} /></div>}
    </div>);
}
function CbCard17({ icon, thumb, title, onX, sent }) {
  return (
    <div className="ff-mc has ff-cb17-c" role="listitem">
      <span className="faces"><span className="f ic">{thumb ? <img src={thumb} alt="" draggable={false} /> : icon}</span></span>
      <b>{title}</b>
      {onX && !sent && <button type="button" className="rm" aria-label={`Remove ${title}`} onClick={onX}><S17I.X size={11} strokeWidth={3} /></button>}
    </div>);
}
function ConfirmBooking17({ ev, setView, bkey }) {
  const { state, dispatch } = useStore();
  const all = useDirectory();
  const info = flowInfo(state, ev);
  const shifts = info.shifts;
  const [d, setD] = useState(() => ({ ...eventDraft11(ev), band: bandOf11(ev), aud: (ev && ev.audience) || "" }));
  const set = (x) => setD(v => ({ ...v, ...x }));
  useEffect(() => {
    const any = d.iso || d.venue.trim() || d.title.trim() || d.kind || d.start || d.band || d.aud;
    if (!any) return;
    const t = setTimeout(() => {
      const ci = cleanIso11(d.iso);
      const data = { ...eventData11({ ...d, iso: ci.past ? ((ev && ev.iso) || "") : ci.iso }), band: "", audience: "", site: "party" };
      if (ev) {
        if (["title", "kind", "iso", "start", "venue", "guests", "band", "audience"].every(k => String(ev[k] || "") === String(data[k] || ""))) return;
        dispatch({ type: "EVENT_PATCH", id: ev.id, patch: data });
        shifts.forEach(sh => dispatch({ type: "SHIFT_PATCH", id: sh.id, patch: { iso: data.iso, date: data.date, venue: data.venue, ...(sh.svcId && sh.svcTime ? { time: svcTimeFor({ time: sh.svcTime }, data.start) } : {}) } }));
      } else {
        const id = uid("evt");
        dispatch({ type: "EVENT_ADD", event: { id, ...data, phone: state.bookPhone || "", email: state.bookEmail || "", questionIds: [] } });
        dispatch({ type: "ACTIVE_EVENT", id });
        if ((state.req17 || {}).draft) dispatch({ type: "V11_SET", patch: { req17: { ...state.req17, [id]: state.req17.draft } } });
        setView({ eventId: id, keep: bkey });
      }
    }, 350);
    return () => clearTimeout(t);
  }, [d]);
  const pkgs = pkgsOf17(state);
  const evId = ev ? ev.id : "";
  const ck = Object.keys(((state.addons17 || {})[evId]) || {}).map(id => ALLCK17.find(y => y.id === id)).filter(Boolean);
  const xa = (((state.xa17 || {})[evId]) || []).map(id => ADDONS17.find(y => y.id === id)).filter(Boolean);
  const goBack = () => { dispatch({ type: "TAB", tab: "network" }); window.scrollTo(0, 0); };
  const drop = (sh) => { dispatch({ type: "SHIFT_DELETE", id: sh.id }); const bk = bkOf17(state); dispatch({ type: "V11_SET", patch: { bk17: { ...bk, pk: bk.pk.filter(x => x !== sh.svcId) } } }); };
  const dropCk = (id) => { const ao = state.addons17 || {}, cur = { ...(ao[evId] || {}) }; delete cur[id]; dispatch({ type: "V11_SET", patch: { addons17: { ...ao, [evId]: cur } } }); };
  const dropXa = (id) => { const xs = state.xa17 || {}; dispatch({ type: "V11_SET", patch: { xa17: { ...xs, [evId]: (xs[evId] || []).filter(x => x !== id) } } }); };
  const dropPerson = (sh, pid) => dispatch({ type: "SHIFT_STAFF", id: sh.id, staffIds: staffOf(sh).filter(x => x !== pid) });
  const sent = info.sent || (ev && paid17(state, ev.id));
  const [stripe, setStripe] = useState(false);
  const [open, setOpen] = useState({ s: true, p: true, e: true, r: true, i: true, f: true });
  const tg = (k) => setOpen(o => ({ ...o, [k]: !o[k] }));
  const missing = [];
  if (!shifts.length) missing.push({ t: "Choose your package first", go: goBack });
  else if (!shifts.every(staffPlanned)) missing.push({ t: "Choose who delivers it", go: goBack });
  if (!d.iso || !d.venue.trim()) missing.push({ t: "Add the date and location", go: () => focusSec("ff-cb17-event") });
  if (!String(contactOf11(state, ev)).trim()) missing.push({ t: "Add your phone number", go: () => { const el = document.getElementById("ff-bill-phone"); if (el) { el.scrollIntoView({ behavior: "smooth", block: "center" }); el.focus(); } } });
  const nSend = new Set(shifts.flatMap(staffOf)).size + shifts.filter(sh => sh.route === "auto").length;
  const confirm = () => {
    if (missing.length) { dispatch({ type: "TOAST", toast: missing[0].t }); missing[0].go(); return; }
    setStripe(true); /* Stripe pay window; the requests go out only once it reports paid */
  };
  const afterPay = () => {
    setStripe(false);
    dispatch({ type: "BOOK_SEND", eventId: ev.id, questions: [] });
    dispatch({ type: "TOAST", toast: `Booking confirmed. Availability requests sent to ${nSend} ${nSend === 1 ? "person" : "people"} on WhatsApp` });
  };
  const gev = ev || { id: "draft", ...eventData11({ ...d }), phone: "", email: "", questionIds: [] };
  const no = "FF-" + (String(gev.id || "").replace(/\D/g, "").slice(-5) || "00001");
  const today = new Date().toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });
  const box = (k, n, id, title, count, children, cls) => (
    <div className={`ff-bsec ${cls} ff-cb17-box`} id={id} key={k}>
      <button type="button" className="ff-bsec-h tap" aria-expanded={open[k]} onClick={() => tg(k)}><span className="n">{n}</span><b>{title}</b>{count ? <em>{count}</em> : null}<span className="dd"><S17I.ChevronDown size={18} className="cv" /></span></button>
      {open[k] && <div className="ff-cb17-in">{children}</div>}
    </div>);
  const sub = (k, Ic, title, children) => (
    <div className="ff-cb17-sub" key={k}>
      <button type="button" className="h" aria-expanded={open[k]} onClick={() => tg(k)}><span className="ic"><Ic size={16} strokeWidth={1.8} /></span><b>{title}</b><S17I.ChevronDown size={18} className="cv" /></button>
      {open[k] && <div className="b">{children}</div>}
    </div>);
  const arrow = (j) => <div className={`ff-barrow j${j}`} aria-hidden="true"><S17I.ChevronDown size={20} strokeWidth={2.4} /></div>;
  const nSvc = shifts.length + ck.length + xa.length, nPeople = new Set(shifts.flatMap(staffOf)).size + shifts.filter(sh => sh.route === "auto").length;
  const payments = ["Apple Pay", "Google Pay", "Card"];
  return (
    <section className="ff-bbox ff-pb ff-cb17" aria-label="Confirm your booking">
      {box("s", 1, "ff-cb17-svc", "Services", nSvc ? `${nSvc} chosen` : "", <>
        <div className="ff-mbasket ff-cb17-bar"><div className="ff-mc-row" role="list" aria-label="Services">
          {shifts.map(sh => { const svc = pkgs.find(y => y.id === sh.svcId); const Ic = (svc && PKICON17[svc.cat]) || S17I.Sparkles; return <CbCard17 sent={sent} key={sh.id} icon={<Ic size={24} strokeWidth={1.5} />} title={sh.role} onX={() => drop(sh)} />; })}
          {ck.map(x => <CbCard17 sent={sent} key={x.id} thumb={x.photo} icon={<S17I.Martini size={24} strokeWidth={1.5} />} title={x.name} onX={() => dropCk(x.id)} />)}
          {xa.map(x => <CbCard17 sent={sent} key={x.id} icon={<x.Ic size={24} strokeWidth={1.5} />} title={x.title} onX={() => dropXa(x.id)} />)}
          {!sent && <button type="button" role="listitem" className="ff-mc add" onClick={goBack} aria-label="Add a package"><span className="faces"><span className="empty"><S17I.Plus size={18} strokeWidth={2.4} /></span></span><b>Add</b></button>}
        </div></div></>, "s1")}
      {arrow(1)}
      {box("p", 2, "ff-cb17-people", "People", nPeople ? `${nPeople} chosen` : "", <>
        <div className="ff-mbasket ff-cb17-bar"><div className="ff-mc-row" role="list" aria-label="People">
          {shifts.flatMap(sh => [
            ...staffOf(sh).map(pid => { const p = findPerson(all, state, pid); return p && <CbCard17 sent={sent} key={sh.id + pid} thumb={p.photo} icon={<S17I.Users size={24} />} title={firstName(p.name)} onX={engFor(state, sh.id, pid) ? null : () => dropPerson(sh, pid)} />; }),
            sh.route === "auto" && <CbCard17 sent={sent} key={sh.id + "auto"} icon={<Coin size={34} tier="gold" />} title="Auto match" onX={() => dispatch({ type: "SHIFT_PATCH", id: sh.id, patch: { route: "" } })} />,
          ]).filter(Boolean)}
          {!sent && <button type="button" role="listitem" className="ff-mc add" onClick={goBack} aria-label="Choose people"><span className="faces"><span className="empty"><S17I.Plus size={18} strokeWidth={2.4} /></span></span><b>Add</b></button>}
        </div></div></>, "s2")}
      {arrow(2)}
      {box("e", 3, "ff-cb17-event", "Event Card", "", <div className="ff-evwrap"><EventCard11 ev={d} edit onPatch={(x) => set(x)} /></div>, "s3")}
      {arrow(3)}
      {box("r", 4, "ff-cb17-review", "Review your order", "", sent && ev ? <ConfirmPanel ev={ev} shifts={shifts} missing={missing} onClose={() => {}} /> : <>
        {sub("i", S17I.FileText, "Invoice and event guide", <EventGuide ev={gev} shifts={shifts} stamp="Preview" />)}
        {sub("f", S17I.Receipt, "FireFlair invoice", <FFInvoice11 shifts={shifts} no={no} today={today} contact={contactOf11(state, ev)} />)}
      </>, "s4")}
      {!sent && <>
        {arrow(3)}
        <div className="ff-cb17-cf">
          <ConfirmSpin17 lines={["Confirm", "booking"]} onClick={confirm} />
          {stripe && <StripePay17 total={POLICY17.feeParty} reference={ev ? ev.id : "draft"} onClose={() => setStripe(false)} onPaid={afterPay} />}
        </div></>}
      <HostDrop17 />
    </section>);
}

/* ======================================================================================================
   v17.4 — FF Admin
   One place to see and manage everything FireFlair holds, across FF Team, FF Staff, FF Party and
   FF VIP. Admins never delete: they hide and show, set verification, and switch sites and features on
   and off. Every change is written to the activity log.

   In this prototype the admin reads this preview's own store (the same data the page saves through the
   `db` capability) plus the demo directory, companies and packages. On the live site every list below
   comes from FireFlair Core through ADMIN_ADAPTER, across every account.
   ====================================================================================================== */

/* What FireFlair Core has to provide for FF Admin. None of it exists yet (FireFlair-Backend has user
   routes only). Every route needs an admin role check; nothing here deletes a record.
   Core: GET   /api/admin/me                         → { tag, role, permissions[] }
   Core: GET   /api/admin/stats                      → counts per collection, hidden counts
   Core: GET   /api/admin/:collection?q=&status=&cursor=   collections: users, cards, companies, packages,
                                                      service-cards, cocktails, stories, events, shifts,
                                                      engagements, reviews, questions, answers, interest,
                                                      availability, terms, invitations, connections
   Core: PATCH /api/admin/:collection/:id/visibility { hidden: true|false, reason? }
   Core: PATCH /api/admin/:collection/:id/verification { tier: "standard"|"bronze"|"silver"|"gold" }
   Core: GET   /api/admin/settings  ·  PATCH /api/admin/settings { sitesOpen[], bookingsLive, xpLive, ... }
   Core: GET   /api/admin/admins    ·  POST /api/admin/admins { tag, role }  ·  PATCH /api/admin/admins/:tag { role?, active? }
   Core: GET   /api/admin/log?cursor=  (append-only: who, what, which record, when)
   Core: GET   /api/admin/export/:collection.csv
   Core: POST  /api/admin/invitations { name, contact, site }  → sends the WhatsApp (or email) invite with a sign-up link
   Core: GET   /api/admin/invitations  ·  POST /api/admin/invitations/:id/resend   (status: sent | joined, joined when the
                                                      contact signs up; match on phone or email)
   Core: GET   /api/admin/bookings?state=&cursor=   events with their shifts and engagements, plus response time
                                                      (first reply in engagement history minus sentAt)
   Core: PATCH /api/admin/engagements/:id { state?, expiresAt?, staffId?, note? }  manual override of any step. Writes
                                                      a history entry { state, at, by: "admin", note } and the admin log;
                                                      a reassign sends a fresh request to the new person
   Core: GET   /api/admin/answers?question_key=&cursor=   every answer as a flat view: account, site, area, question,
                                                      question_key, answer, answered_at
   Public read routes (GET /api/user/card/public/:ffTag, lists, search) must leave out hidden records. */
const ADMIN_ADAPTER = { connected: false, note: "Prototype: FF Admin reads and changes this preview's data only." };

/* ---- Analytics framework (v17.3.41) -------------------------------------------------------------------
   Tracking is on for every visitor from the moment they land. There is no cookie banner: the live site
   covers it in the terms and conditions and the privacy policy (to be written, Phase 2 or 3).

   The page records, for every visitor:
     session_start  once per visit: referrer, campaign tags (utm_*), language, time zone, screen and window size,
                    device type, browser, whether the visitor is signed in
     view           a screen opened (site / tab / route), and view_end with the time spent (ms) and how far down the
                    page they scrolled (%)
     shown          the buttons and links visible on that screen, once per view. Compared with clicks this gives
                    "seen but not clicked"
     click          the label of the button or link (aria-label, else its text, 60 chars)
     field          a form field was started or left empty: its label only, never what was typed. This shows which
                    questions people skip
     sign_in, profile_live, booking_request, event_created, site_switch   funnel steps, from the state
   Every event carries a session id, the time, the screen and the window width. Typed text is never recorded.

   Live site (Phase 2 framework, deeper analysis Phase 2.5 / 3):
     Platform: a product-analytics service does the heavy lifting (sessions, funnels, heatmaps, replays).
       Recommended: PostHog (EU cloud) or GA4. ANALYTICS_ADAPTER.send() is the only place the page talks to it.
     Core: POST /api/analytics/events  [{ type, at, sid, screen, label?, ms?, scroll?, w }].
       Core adds what the page can't know reliably: IP address, approximate location from the IP, user agent,
       and links the session to the account once the visitor signs in.
     Core: GET  /api/admin/analytics/summary?from=&to=   screens by visits, time and scroll depth, top clicks,
       seen-not-clicked, skipped fields, funnel (landed -> signed up -> profile live -> first booking), visitors by
       area, device and source.
     Legal: say what is tracked in the terms and conditions and a privacy policy before launch. Take legal advice
       on tracking linked to named people and on session replay, which may need consent. */
const ANALYTICS_ADAPTER = {
  connected: false,
  platform: "Not connected",
  send(events) { /* Live: posthog.capture(...) or fetch("/api/analytics/events", { method: "POST", body: JSON.stringify(events) }) */ },
};
const AN17 = { events: [], sid: `s_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`, cur: null, since: 0, scroll: 0, started: false, l: new Set(), t: null };
const AN17_KEY = "ff_analytics17";
(function an17Load() {
  try { const raw = localStorage.getItem(AN17_KEY); if (raw) { const v = JSON.parse(raw); AN17.events = Array.isArray(v.events) ? v.events.slice(-3000) : []; } } catch (e) {}
})();
const an17Save = () => { clearTimeout(AN17.t); AN17.t = setTimeout(() => { try { localStorage.setItem(AN17_KEY, JSON.stringify({ events: AN17.events.slice(-3000) })); } catch (e) {} }, 400); };
const an17Emit = () => AN17.l.forEach(f => f());
function track17(type, props = {}) {
  const ev = { type, at: Date.now(), sid: AN17.sid, screen: AN17.cur, w: window.innerWidth, ...props };
  AN17.events.push(ev); if (AN17.events.length > 3000) AN17.events.splice(0, AN17.events.length - 3000);
  ANALYTICS_ADAPTER.send([ev]); an17Save(); an17Emit();
}
function clearAnalytics17() { AN17.events = []; an17Save(); an17Emit(); }
function useAn17() { const [, f] = useState(0); useEffect(() => { const g = () => f(n => n + 1); AN17.l.add(g); return () => AN17.l.delete(g); }, []); return AN17; }
const an17Label = (el) => (el.getAttribute("aria-label") || el.innerText || el.getAttribute("title") || el.getAttribute("placeholder") || "").replace(/\s+/g, " ").trim().slice(0, 60);
const AN17_SEL = "button, a, [role=button], [role=tab], [role=switch], summary, select";
const AN17_SKIP = ".ff-adm";
function an17Session(signedIn) {
  if (AN17.started) return; AN17.started = true;
  const q = new URLSearchParams(location.search), ua = navigator.userAgent || "";
  const utm = {}; ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content"].forEach(k => { if (q.get(k)) utm[k] = q.get(k); });
  let tz = ""; try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone; } catch (e) {}
  track17("session_start", { referrer: document.referrer || "", utm, lang: navigator.language || "", tz, screenW: screen.width, screenH: screen.height, winW: window.innerWidth, winH: window.innerHeight,
    device: /Mobi|Android|iPhone/i.test(ua) ? "phone" : /iPad|Tablet/i.test(ua) ? "tablet" : "desktop", browser: /Edg\//.test(ua) ? "Edge" : /Chrome\//.test(ua) ? "Chrome" : /Safari\//.test(ua) ? "Safari" : /Firefox\//.test(ua) ? "Firefox" : "Other", signedIn: !!signedIn });
}
function an17Shown() {
  if (AN17.cur === "FF Admin") return;
  const seen = new Set();
  document.querySelectorAll(AN17_SEL).forEach(el => { if (seen.size >= 60 || el.closest(AN17_SKIP)) return; const r = el.getBoundingClientRect(); if (!r.width || r.bottom < 0 || r.top > window.innerHeight * 2) return; const l = an17Label(el); if (l) seen.add(l); });
  if (seen.size) track17("shown", { labels: [...seen] });
}
const an17Depth = () => { const h = Math.max(document.documentElement.scrollHeight - window.innerHeight, 1); return Math.min(100, Math.round((window.scrollY / h) * 100)); };
function an17ViewEnd() { if (AN17.cur && AN17.since) track17("view_end", { ms: Date.now() - AN17.since, scroll: AN17.scroll }); AN17.since = 0; AN17.scroll = 0; }
/* Runs in the root render. Watches the screen and a few funnel signals; a few listeners for the whole page. */
function useAnalytics17(state) {
  const site = state.role === "team" ? "FF Team" : state.site === "party" ? "FF Party" : state.role === "staff" ? "FF Staff" : "FF Team";
  const screen = state.adminOpen17 ? "FF Admin" : [site, state.viewingCompany ? "company page" : state.viewing ? "profile page" : (state.tab || "home"), typeof state.route === "string" && !/home|entry/i.test(state.route) ? state.route : ""].filter(Boolean).join(" / ");
  const prev = useRef({});
  useEffect(() => {
    an17Session(state.auth && state.auth.tag);
    if (screen === AN17.cur) return;
    an17ViewEnd(); AN17.cur = screen; AN17.since = Date.now(); track17("view", {});
    const t = setTimeout(an17Shown, 900); return () => clearTimeout(t);
  }, [screen]);
  useEffect(() => {
    const p = prev.current, signedIn = !!(state.auth && state.auth.tag), live = !!(state.profile && state.profile.live), n = (state.engagements || []).length, ev = (state.events || []).length;
    if (p.init) {
      if (signedIn && !p.signedIn) track17("sign_in", { site: state.site });
      if (live && !p.live) track17("profile_live", {});
      if (n > p.n) track17("booking_request", { count: n - p.n });
      if (ev > p.ev) track17("event_created", { site: state.site });
      if (state.site !== p.site) track17("site_switch", { to: state.site });
    }
    prev.current = { init: true, signedIn, live, n, ev, site: state.site };
  });
  useEffect(() => {
    const onClick = (e) => { const el = e.target.closest && e.target.closest(AN17_SEL); if (!el || el.closest(AN17_SKIP)) return; const label = an17Label(el); if (label) track17("click", { label }); };
    const FIELD = "input, textarea";
    const touched = new Map();
    const onFocus = (e) => { const el = e.target; if (!el.matches || !el.matches(FIELD) || el.closest(AN17_SKIP) || el.type === "password") return; const l = an17Label(el); if (l && !touched.has(el)) { touched.set(el, l); track17("field", { label: l, action: "start" }); } };
    const onBlur = (e) => { const el = e.target; if (!el.matches || !el.matches(FIELD) || !touched.has(el)) return; if (!String(el.value || "").trim()) track17("field", { label: touched.get(el), action: "empty" }); touched.delete(el); };
    const onScroll = () => { const d = an17Depth(); if (d > AN17.scroll) AN17.scroll = d; };
    const onHide = () => { if (document.visibilityState === "hidden") { an17ViewEnd(); } else if (AN17.cur) { AN17.since = Date.now(); } };
    document.addEventListener("click", onClick, true); document.addEventListener("focusin", onFocus); document.addEventListener("focusout", onBlur);
    window.addEventListener("scroll", onScroll, { passive: true }); document.addEventListener("visibilitychange", onHide); window.addEventListener("pagehide", an17ViewEnd);
    return () => { document.removeEventListener("click", onClick, true); document.removeEventListener("focusin", onFocus); document.removeEventListener("focusout", onBlur); window.removeEventListener("scroll", onScroll); document.removeEventListener("visibilitychange", onHide); window.removeEventListener("pagehide", an17ViewEnd); };
  }, []);
}

const A17I = {
  Dash: lucideIcon("LayoutDashboard"), Globe: lucideIcon("Globe"), Users: lucideIcon("Users"), Brief: lucideIcon("Briefcase"),
  Layers: lucideIcon("Layers"), Cal: lucideIcon("CalendarDays"), Msg: lucideIcon("MessageSquare"), Star: lucideIcon("Star"),
  Shield: lucideIcon("ShieldCheck"), Hist: lucideIcon("History"), Db: lucideIcon("Database"), Eye: lucideIcon("Eye"),
  EyeOff: lucideIcon("EyeOff"), X: lucideIcon("X"), Search: lucideIcon("Search"), Copy: lucideIcon("Copy"),
  Refresh: lucideIcon("RefreshCw"), Plus: lucideIcon("Plus"), ChevronDown: lucideIcon("ChevronDown"), Lock: lucideIcon("Lock"),
  Party: lucideIcon("PartyPopper"), Send: lucideIcon("Send"), Chart: lucideIcon("BarChart3"),
};

const ADM17_KINDS = ["people", "companies", "guests", "packages", "cards", "reviews", "events", "questions"];
const ADM17_DEFAULT = {
  hidden: Object.fromEntries(ADM17_KINDS.map(k => [k, {}])),
  tier: { people: {}, companies: {}, guests: {} },
  flags: null,
  invites: [],
  admins: [{ tag: "ALEXG", name: "Alex Gagnon", role: "owner", active: true, since: "2026-10-31" }],
  log: [],
  viewAs: "owner",
};
const adm17 = (s) => {
  const a = (s && s.admin17) || {};
  return { ...ADM17_DEFAULT, ...a, hidden: { ...ADM17_DEFAULT.hidden, ...(a.hidden || {}) }, tier: { ...ADM17_DEFAULT.tier, ...(a.tier || {}) },
    admins: a.admins || ADM17_DEFAULT.admins, log: a.log || [], invites: a.invites || [] };
};
const hid17 = (state, kind, id) => !!(state && state.admin17 && state.admin17.hidden && state.admin17.hidden[kind] && state.admin17.hidden[kind][id]);

const ADM17_ROLES = {
  owner: { label: "Owner", can: ["hide", "verify", "sites", "data", "admins", "export"] },
  admin: { label: "Admin", can: ["hide", "verify", "sites", "data", "export"] },
  gold: { label: "Gold package", can: ["hide", "verify"] },
};
const ADM17_PERMS = [["hide", "Hide and show content"], ["verify", "Set verification"], ["sites", "Switch sites and features"], ["data", "See answers, sign-ups and the database"], ["admins", "Manage admins"], ["export", "Copy data out"]];
/* Verification. The prototype's "standard" is Core's "base" (users.verification_level: base | bronze | silver | gold). */
const TIERS17 = [["standard", "Base"], ["bronze", "Bronze"], ["silver", "Silver"], ["gold", "Gold"]];
/* Question Cards: prototype id → Core question_master.question_key (scripts/seedQuestions.js). */
const CORE_QUESTION_KEYS = {
  g_travel: "generic_travel_to_events", g_freelance: "generic_freelance_availability", g_equipment: "generic_own_equipment",
  g_notice: "generic_short_notice_availability", g_events: "generic_event_experience",
  f_ease: "feedback_profile_creation_ease", f_confusing: "feedback_profile_confusion", f_useful: "feedback_profile_usefulness",
  f_cv: "feedback_use_as_cv", f_improve: "feedback_improvement_suggestions",
};

/* ---- State ---------------------------------------------------------------------------------------- */
function admin17Reduce(s, a) {
  const A = adm17(s);
  const by = String((s.auth && s.auth.tag) || "DEV").toUpperCase();
  const entry = (action, kind, ref, label) => [{ id: `log_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`, at: Date.now(), by, action, kind, ref, label }, ...A.log].slice(0, 1000);
  switch (a.op) {
    case "hide": case "show": {
      const on = a.op === "hide";
      return { ...s, admin17: { ...A, hidden: { ...A.hidden, [a.kind]: { ...A.hidden[a.kind], [a.id]: on } }, log: entry(on ? "Hid" : "Showed", a.kind, a.id, a.label) } };
    }
    case "tier":
      return { ...s, admin17: { ...A, tier: { ...A.tier, [a.kind]: { ...A.tier[a.kind], [a.id]: a.value } }, log: entry(`Set verification to ${a.value}`, a.kind, a.id, a.label) } };
    case "flag": {
      const f = { ...(A.flags || {}), [a.key]: a.value };
      return { ...s, admin17: { ...A, flags: f, log: entry(`${a.value ? "Turned on" : "Turned off"}`, "settings", a.key, a.label) } };
    }
    case "site": {
      const cur = (A.flags && A.flags.sitesOpen) || (P1_DEF17 ? P1_DEF17.sitesOpen : PHASE1.sitesOpen);
      const next = a.value ? [...new Set([...cur, a.key])] : cur.filter(k => k !== a.key);
      return { ...s, admin17: { ...A, flags: { ...(A.flags || {}), sitesOpen: next }, log: entry(a.value ? "Made live" : "Took offline", "sites", a.key, a.label) } };
    }
    case "admin_add": {
      const tag = String(a.tag || "").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 8);
      if (!tag || A.admins.some(x => x.tag === tag)) return s;
      return { ...s, admin17: { ...A, admins: [...A.admins, { tag, name: a.name || "", role: a.role || "admin", active: true, since: TODAY_ISO }], log: entry(`Added as ${(ADM17_ROLES[a.role] || {}).label || "Admin"}`, "admins", tag, tag) } };
    }
    case "admin_set":
      return { ...s, admin17: { ...A, admins: A.admins.map(x => x.tag === a.tag ? { ...x, ...a.patch } : x),
        log: entry(a.patch.active === false ? "Deactivated" : a.patch.active === true ? "Reactivated" : `Role set to ${(ADM17_ROLES[a.patch.role] || {}).label}`, "admins", a.tag, a.tag) } };
    case "viewAs": return { ...s, admin17: { ...A, viewAs: a.value } };
    /* Invitations to join. Core sends them on WhatsApp (or email) with a sign-up link; the prototype records them. */
    case "invite": {
      const inv = { id: uid("inv"), name: String(a.name || "").trim(), contact: String(a.contact || "").trim(), site: a.site || "team", at: Date.now(), by, status: "sent", sends: 1 };
      if (!inv.contact) return s;
      return { ...s, admin17: { ...A, invites: [inv, ...A.invites], log: entry(`Invited to ${SITE_NAME17[inv.site]}`, "invites", inv.id, inv.name || inv.contact) } };
    }
    case "invite_resend":
      return { ...s, admin17: { ...A, invites: A.invites.map(x => x.id === a.id ? { ...x, at: Date.now(), sends: (x.sends || 1) + 1 } : x), log: entry("Resent invitation", "invites", a.id, a.label) } };
    /* Manual override of a booking request. Every change is added to the request's own history and the admin log. */
    case "eng_state":
      return { ...s, engagements: s.engagements.map(e => e.id === a.id ? { ...e, state: a.value, history: [...(e.history || []), { state: a.value, at: Date.now(), by: "admin" }] } : e),
        admin17: { ...A, log: entry(`Booking set to ${ENG_LABEL[a.value] || a.value}`, "bookings", a.id, a.label) } };
    case "eng_extend":
      return { ...s, engagements: s.engagements.map(e => e.id === a.id ? { ...e, state: e.state === "expired" ? "requested" : e.state, expiresAt: Math.max(Date.now(), e.expiresAt || 0) + 864e5,
        history: [...(e.history || []), { state: e.state === "expired" ? "requested" : e.state, at: Date.now(), by: "admin", note: "extended 24h" }] } : e),
        admin17: { ...A, log: entry("Extended the reply window by 24 hours", "bookings", a.id, a.label) } };
    case "eng_reassign": {
      const eng = s.engagements.find(e => e.id === a.id); if (!eng || !a.to) return s;
      return { ...s,
        engagements: s.engagements.map(e => e.id === a.id ? { ...e, staffId: a.to, state: "requested", sentAt: Date.now(), expiresAt: Date.now() + RESPONSE_MS, history: [...(e.history || []), { state: "requested", at: Date.now(), by: "admin", note: `reassigned from ${eng.staffId}` }] } : e),
        shifts: s.shifts.map(x => x.id === eng.shiftId ? { ...x, staffIds: staffOf(x).map(id => id === eng.staffId ? a.to : id), staffId: x.staffId === eng.staffId ? a.to : x.staffId } : x),
        admin17: { ...A, log: entry("Reassigned a booking request", "bookings", a.id, a.label) } };
    }
    default: return s;
  }
}

/* ---- Applying admin choices to the three sites ----------------------------------------------------- */
let PS_ALL17 = null, P1_DEF17 = null;
const allPackages17 = () => {
  const base = PS_ALL17 || PARTY_SERVICES;
  return [...(base.some(x => x.id === "svc_staffing") ? base : [...base, STAFFING_SERVICE]), ...DJ_PKGS17];
};
function applyAdmin17(state) {
  if (!PS_ALL17) PS_ALL17 = PARTY_SERVICES.slice();
  if (!P1_DEF17) P1_DEF17 = { sitesOpen: PHASE1.sitesOpen.slice(), bookingsLive: PHASE1.bookingsLive, xpLive: PHASE1.xpLive, leaderboards: PHASE1.leaderboards, desktopAdd: PHASE1.desktopAdd };
  const A = state.admin17;
  const hp = (A && A.hidden && A.hidden.packages) || {};
  const want = PS_ALL17.filter(x => !hp[x.id]);
  if (want.length !== PARTY_SERVICES.length || want.some((x, i) => PARTY_SERVICES[i] !== x)) PARTY_SERVICES.splice(0, PARTY_SERVICES.length, ...want);
  const f = { ...P1_DEF17, ...((A && A.flags) || {}) };
  PHASE1.sitesOpen = f.sitesOpen; PHASE1.bookingsLive = f.bookingsLive; PHASE1.xpLive = f.xpLive; PHASE1.leaderboards = f.leaderboards; PHASE1.desktopAdd = f.desktopAdd;
}
/* People and companies as the public sees them: hidden ones left out, verification as set by an admin. */
function adminPeople17(state, list) {
  const A = state && state.admin17;
  if (!A) return list;
  const h = (A.hidden && A.hidden.people) || {}, t = (A.tier && A.tier.people) || {};
  return list.filter(p => !h[p.id]).map(p => t[p.id] ? { ...p, tier: t[p.id] } : p);
}
function adminCompanies17(state, list) {
  const A = state && state.admin17;
  if (!A) return list;
  const h = (A.hidden && A.hidden.companies) || {}, t = (A.tier && A.tier.companies) || {};
  return list.filter(c => c && !h[c.id]).map(c => t[c.id] ? { ...c, tier: t[c.id] } : c);
}

/* ---- Reading everything ---------------------------------------------------------------------------- */
const fmt17 = (v) => {
  if (v === undefined || v === null || v === "") return "";
  if (Array.isArray(v)) return v.map(fmt17).filter(Boolean).join(", ");
  if (typeof v === "object") return Object.entries(v).filter(([k]) => !["account", "at"].includes(k)).map(([k, x]) => `${k}: ${fmt17(x)}`).filter(x => !/: $/.test(x)).join(" · ");
  return String(v);
};
const when17 = (t) => { if (!t) return ""; const d = new Date(t); return isNaN(d) ? "" : d.toLocaleString("en-GB", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" }); };
const acct17 = (state) => String(state.auth.tag || state.session.tag || "").toUpperCase() || String(state.profile.name || "").trim() || "This browser";

function peopleAll17(state) {
  const me = String(state.profile.name || "").trim() ? [{ ...meAsStaff(state.profile, state.session), id: "me", src: "This account" }] : [];
  return [...me, ...(state.directory || []).map(p => ({ ...p, src: (state.joinedPeople || []).some(j => j.id === p.id) ? "Joined" : "Directory" }))];
}
function companiesAll17(state) {
  return [
    ...(state.company && String(state.company.name || "").trim() ? [{ ...companyById(state, "mine"), src: "This account" }] : []),
    ...COMPANIES.map(x => companyById(state, x.id)).filter(Boolean).map(c => ({ ...c, src: "Directory" })),
  ];
}
const SITE_NAME17 = { team: "FF Team", staff: "FF Staff", party: "FF Party" };
/* FF Party guests (customers). The prototype keeps a host's details on the same account record as a business. */
function guestsAll17(state) {
  const c = state.company || {};
  const mine = String(c.name || "").trim() && (c.partyStyle || c.usualArea || state.site === "party") ? [{ ...c, id: "mine", src: "This account" }] : [];
  return [...mine, { ...DEMO_HOST17, id: "guest_demo", src: "Demo host" }];
}
function cardsAll17(state) {
  return [
    ...(state.myServices || []).filter(x => String(x.title || "").trim()).map(x => ({ id: x.id, type: "Service card", title: x.title, sub: x.type === "addon" ? "Add-on" : "Package", by: acct17(state) })),
    ...(state.myCocktails || []).filter(x => String(x.name || "").trim()).map(x => ({ id: x.id, type: x.style === "classic" ? "Classic cocktail" : "Signature cocktail", title: x.name, sub: x.base || x.glass || "", by: acct17(state) })),
    ...(state.myPosts || []).filter(x => String(x.title || "").trim()).map(x => ({ id: x.id, type: "Story", title: x.title, sub: x.place || "", by: acct17(state) })),
  ];
}
function reviewsAll17(state, people) {
  const name = (id) => ((people.find(p => p.id === id) || {}).name) || id || "";
  const recs = (((state.profile || {}).records || {}).reviews || []).map(r => ({ id: r.id, about: String(state.profile.name || "This account"), by: r.byName || r.from || (r.details && r.details.employer) || "", text: r.description || r.text || r.name || "", rating: r.rating, at: r.at || r.createdAt }));
  const given = (state.reviews || []).map(r => ({ id: r.id, about: name(r.personId || r.aboutId || r.to), by: acct17(state), text: r.text || r.review || "", rating: r.rating, at: r.at }));
  const invites = (state.teamInvites || []).filter(x => String(x.review || "").trim()).map(x => ({ id: x.id, about: x.name || name(x.personId), by: acct17(state), text: x.review, rating: x.rating, at: x.at, status: x.status }));
  const companies = ((state.company && state.company.reviews) || []).map(r => ({ id: r.id, about: state.company.name || "Your business", by: r.byName || r.by || "", text: r.text || "", rating: r.rating, at: r.at }));
  return [...recs, ...given, ...invites, ...companies].filter(r => r.id);
}
function qaRows17(state, people) {
  const rows = [], me = acct17(state);
  const add = (area, q, a, extra = {}) => { const s = fmt17(a); if (s) rows.push({ area, q, a: s, account: me, ...extra }); };
  const answers = state.profile.answers || {};
  Object.entries(answers).forEach(([k, v]) => {
    if (k.startsWith("av_")) add("Availability", `Available on ${shortDay(k.slice(3))}`, v);
    else { const q = QUESTIONS.find(x => x.id === k); add(q && q.group === "hiring" ? "Hiring questions" : "Question cards", q ? q.text : k, v, { key: CORE_QUESTION_KEYS[k] || "" }); }
  });
  Object.entries(state.feedback || {}).forEach(([k, v]) => { const q = QUESTIONS.find(x => x.id === k); add("Feedback", q ? q.text : k, v, { key: CORE_QUESTION_KEYS[k] || "" }); });
  (state.profile.aiQuestions || []).forEach(q => add("Suggested questions", q.text, q.answer));
  (state.profileQuestions || []).forEach(q => rows.push({ area: "Asked on profiles", q: q.text, a: fmt17(q.answer) || "Not answered yet", account: q.by || "Visitor",
    about: ((people.find(p => p.id === q.personId) || {}).name) || q.personId, hideId: q.id, at: q.askedAt }));
  const pick = (list, ids) => (ids || []).map(id => (list.find(x => x.id === id) || {}).title || id);
  const ti = state.trainingInterest, ji = state.jobsInterest, ri = state.rewardsInterest;
  if (ti) [...pick(TRAINING_COURSES, ti.courses), ...(ti.own || [])].forEach(t => rows.push({ area: "Training", q: "Interested in", a: t, account: ti.account || me, at: ti.at }));
  if (ji) [...pick(DREAM_JOBS, ji.jobs), ...(ji.dream || [])].forEach(t => rows.push({ area: "Dream jobs", q: "Interested in", a: t, account: ji.account || me, at: ji.at }));
  if (ri) [...pick(XP_REWARDS, ri.rewards), ...(ri.own || [])].forEach(t => rows.push({ area: "FF rewards", q: "Interested in", a: t, account: ri.account || me, at: ri.at }));
  if (state.vipInterest) add("FF VIP", "Register interest", state.vipInterest);
  const pk = allPackages17();
  (state.profile.serviceInterest || []).forEach(id => rows.push({ area: "Party card sign-ups", q: "Signed up for", a: (pk.find(x => x.id === id) || {}).title || id, account: me }));
  if ((state.profile.unavail17 || []).length) add("Availability", "Not available", [...state.profile.unavail17].sort().map(shortDay));
  (state.availabilityAsks || []).forEach(x => add("Availability requests", x.text || x.role || "Availability request", x));
  if (state.myTerms17) MY_TERMS17.forEach(t => add("Personal terms", t.label, state.myTerms17[t.k]));
  if (state.svcTerms17) TERMS17.forEach(t => add("Service card terms", t.label, state.svcTerms17[t.k]));
  (state.partyEvents || []).forEach(x => add("Party leads", x.title || x.kind || "Event Card", x));
  return rows;
}

/* ---- Small parts ------------------------------------------------------------------------------------ */
function Sw17({ on, onChange, disabled, label }) {
  return (
    <button type="button" role="switch" aria-checked={!!on} aria-label={label} disabled={disabled} className={`ff-adm-sw${on ? " on" : ""}`} onClick={() => !disabled && onChange(!on)}>
      <i aria-hidden="true" />
    </button>
  );
}
function Vis17({ hidden, onToggle, can }) {
  return (
    <button type="button" className={`ff-adm-vis${hidden ? " off" : ""}`} disabled={!can} onClick={onToggle} aria-pressed={!hidden}>
      {hidden ? <><A17I.EyeOff size={13} /> Hidden</> : <><A17I.Eye size={13} /> Live</>}
    </button>
  );
}
function Search17({ value, onChange, placeholder }) {
  return <label className="ff-adm-q"><A17I.Search size={15} /><input value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} aria-label={placeholder} /></label>;
}
function AdmChips17({ value, onChange, options }) {
  return <div className="ff-adm-chips" role="group">{options.map(([k, l, n]) => <button key={k} type="button" aria-pressed={value === k} className={value === k ? "on" : ""} onClick={() => onChange(k)}>{l}{n != null && <em>{n}</em>}</button>)}</div>;
}
const match17 = (q, ...parts) => { const n = String(q || "").trim().toLowerCase(); return !n || parts.join(" ").toLowerCase().includes(n); };
