/* ---- ported from v1.01: hooks/useScroller.ts ---- */

/** State for a horizontal carousel: which ends it has reached, the card in
 *  view, whether it has been swiped yet, and a by(+1 / -1) step. */
function useScroller(step) {
    const ref = useRef(null);
    const [edge, setEdge] = useState({ start: true, end: false });
    const [active, setActive] = useState(0);
    const [moved, setMoved] = useState(false);
    useDragScroll(ref);
    const update = useCallback(() => {
        const el = ref.current;
        if (!el)
            return;
        let best = 0;
        let d = Infinity;
        Array.from(el.children).forEach((k, i) => {
            const x = Math.abs(k.offsetLeft - el.offsetLeft - el.scrollLeft - 4);
            if (x < d) {
                d = x;
                best = i;
            }
        });
        setActive(best);
        setEdge({ start: el.scrollLeft < 12, end: el.scrollLeft + el.clientWidth >= el.scrollWidth - 12 });
        if (el.scrollLeft > 20)
            setMoved(true);
    }, []);
    useEffect(() => {
        update();
        const el = ref.current;
        if (!el)
            return;
        el.addEventListener("scroll", update, { passive: true });
        window.addEventListener("resize", update);
        return () => {
            el.removeEventListener("scroll", update);
            window.removeEventListener("resize", update);
        };
    }, [update]);
    const by = (dir) => {
        const el = ref.current;
        if (el)
            el.scrollBy({ left: dir * Math.max(step, el.clientWidth * 0.8), behavior: "smooth" });
    };
    return { ref, edge, active, moved, by };
}

/* ---- ported from v1.01: hooks/useEdgeBounce.ts ---- */

/** v1.01: the pull-and-spring-back at the top and bottom of a page, applied to
 *  the page content only - the mobile home bar stays where it is. Touch only.
 *  Home's own end-of-page pull belongs to the coin game, so that edge is left to it. */
function useEdgeBounce(selector = "main") {
    useEffect(() => {
        let el = null;
        const root = document.documentElement;
        let startY = 0;
        let edge = null;
        let pull = 0;
        const atTop = () => window.scrollY <= 0;
        const atBottom = () => window.innerHeight + window.scrollY >= root.scrollHeight - 1;
        const set = (v, spring) => {
            el = el ?? document.querySelector(selector);
            if (!el)
                return;
            pull = v;
            el.style.transition = spring ? "transform .5s cubic-bezier(.34,1.56,.64,1)" : "none";
            el.style.transform = v ? `translateY(${v.toFixed(1)}px)` : "";
        };
        const onStart = (e) => {
            startY = e.touches[0].clientY;
            edge = null;
            if (el?.style.transform)
                set(0, false);
        };
        const onMove = (e) => {
            const dy = e.touches[0].clientY - startY;
            if (!edge) {
                if (dy > 4 && atTop())
                    edge = "top";
                else if (dy < -4 && atBottom() && !document.querySelector(".ff-drop"))
                    edge = "bottom";
                if (edge)
                    startY = e.touches[0].clientY;
                return;
            }
            const d = e.touches[0].clientY - startY;
            if ((edge === "top" && d <= 0) || (edge === "bottom" && d >= 0))
                return set(0, false);
            set(Math.sign(d) * Math.min(70, Math.abs(d) * 0.35), false);
        };
        const onEnd = () => {
            if (pull)
                set(0, true);
            edge = null;
        };
        window.addEventListener("touchstart", onStart, { passive: true });
        window.addEventListener("touchmove", onMove, { passive: true });
        window.addEventListener("touchend", onEnd, { passive: true });
        window.addEventListener("touchcancel", onEnd, { passive: true });
        return () => {
            window.removeEventListener("touchstart", onStart);
            window.removeEventListener("touchmove", onMove);
            window.removeEventListener("touchend", onEnd);
            window.removeEventListener("touchcancel", onEnd);
            if (el)
                el.style.transform = "";
        };
    }, [selector]);
}

