/* ---- Scene: drawn stand-in for a photo ----------------------------------- */
const sceneRnd = (seed, i) => {
    const x = Math.sin((i + 1) * 127.1 + seed * 311.7) * 43758.5453;
    return x - Math.floor(x);
};
const Coupe = ({ x, y, s = 1 }) => (<g transform={`translate(${x} ${y}) scale(${s})`}><path d="M0 0h44c0 17-10 27-22 27S0 17 0 0z M22 27v28 M8 55h28"/></g>);
const High = ({ x, y, s = 1 }) => (<g transform={`translate(${x} ${y}) scale(${s})`}><path d="M0 0h28l-3 56H3z M4 14h20"/></g>);
const Shaker = ({ x, y, s = 1 }) => (<g transform={`translate(${x} ${y}) scale(${s})`}><path d="M7 0h14l-1 12H8z M3 12h22l-3 46H6z"/></g>);
const Bottle = ({ x, y, h = 70, s = 1 }) => (<g transform={`translate(${x} ${y}) scale(${s})`}><path d={`M8 0h8v${h * 0.32}l5 8v${h * 0.6}H3V${h * 0.32 + 8}l5-8z`}/></g>);
/** A drawn bar (or festival) scene - the backdrop behind previews, and the
 *  fallback wherever there's no photograph. */
function HomeScene({ kind = "bar" }) {
    const seed = kind.length * 7 + kind.charCodeAt(0);
    const dots = Array.from({ length: 24 }, (_, i) => ({
        x: sceneRnd(seed, i) * 400,
        y: sceneRnd(seed, i + 40) * 190 + 6,
        r: 5 + sceneRnd(seed, i + 80) * 20,
        o: 0.06 + sceneRnd(seed, i + 120) * 0.2,
        c: i % 3 ? "#E4C36A" : "#F4EBD6",
    }));
    return (<svg className="ff-scene" viewBox="0 0 400 300" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">
      {dots.map((d, i) => <circle key={i} cx={d.x} cy={d.y} r={d.r} fill={d.c} opacity={d.o}/>)}
      {kind === "festival" ? (<g>
          <path d="M-10 40 Q100 110 200 56 T410 50" fill="none" stroke="#C9A227" strokeOpacity=".55" strokeWidth="1.4"/>
          {[18, 62, 108, 154, 200, 246, 292, 338, 382].map((x, i) => (<circle key={i} cx={x} cy={52 + Math.sin(i * 1.1) * 22 + 22} r="5" fill="#F7E3A0" opacity=".9"/>))}
          <g fill="rgba(244,235,214,.07)" stroke="#C9A227" strokeOpacity=".5" strokeWidth="1.2">
            <path d="M20 250 L110 168 L200 250z"/>
            <path d="M170 250 L270 150 L370 250z"/>
          </g>
          <rect x="0" y="244" width="400" height="56" fill="#0E0809"/>
          <rect x="0" y="244" width="400" height="3" fill="#C9A227" opacity=".7"/>
          <g fill="rgba(244,235,214,.08)" stroke="#E4C36A" strokeWidth="1.4" strokeLinejoin="round">
            <Coupe x={120} y={196} s={0.7}/><High x={186} y={200} s={0.75}/>
            <Shaker x={238} y={190} s={0.75}/><High x={290} y={200} s={0.75}/>
          </g>
        </g>) : (<g>
          <rect x="0" y="238" width="400" height="62" fill="#0E0809"/>
          <rect x="0" y="238" width="400" height="3" fill="#C9A227" opacity=".7"/>
          <g fill="rgba(244,235,214,.07)" stroke="#E4C36A" strokeWidth="1.4" strokeLinejoin="round" strokeLinecap="round">
            <Bottle x={26} y={150} h={80}/><Bottle x={58} y={162} h={68} s={0.95}/><Bottle x={92} y={146} h={86}/>
            <Coupe x={158} y={186}/><Shaker x={232} y={176} s={1.1}/><High x={290} y={180} s={1.05}/><Bottle x={346} y={156} h={78}/>
          </g>
        </g>)}
    </svg>);
}
/** A horizontal row of cards with previous / next buttons, swipe and drag. */
function HomeCarousel({ label, children }) {
    const { ref, edge, by } = useScroller(220);
    const items = Children.toArray(children).filter(Boolean);
    return (<div className="ff-hc" role="region" aria-roledescription="carousel" aria-label={label}>
      <button type="button" className="ff-hc-btn prev" aria-label="Previous" disabled={edge.start} onClick={() => by(-1)}>
        <ChevronLeft size={18}/>
      </button>
      <div className="ff-hc-track" ref={ref} tabIndex={0}>
        {items.map((c, i) => <div className="ff-hc-item" key={i}>{c}</div>)}
      </div>
      <button type="button" className="ff-hc-btn next" aria-label="Next" disabled={edge.end} onClick={() => by(1)}>
        <ChevronRight size={18}/>
      </button>
    </div>);
}
function Sect({ id, eyebrow, title, lede, badge, boxed, className, children }) {
    const inner = (<>
      {(eyebrow || title) && (<div className="ff-sect-head">
          {badge && <div className="mb-2.5">{badge}</div>}
          {eyebrow && <div className="ff-eyebrow">{eyebrow}</div>}
          {title && <h2 className="ff-h1 mt-1.5">{title}</h2>}
          {lede && <p className="ff-lede mt-2.5 mb-0">{lede}</p>}
        </div>)}
      {children}
    </>);
    return (<section className={`ff-sect${boxed ? " boxed" : ""}${className ? ` ${className}` : ""}`} id={id}>
      {boxed ? <div className={`ff-bigsq${boxed === "dark" ? " dark" : ""}`}>{inner}</div> : inner}
    </section>);
}
/* ---- Line marks for the Build / Share / Grow medals ----------------------- */
function PromiseMark({ mark, size = 24 }) {
    const p = { fill: "none", stroke: "currentColor", strokeWidth: 1.6, strokeLinecap: "round", strokeLinejoin: "round" };
    return (<svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" className="block">
      {mark === "connect" && (<>
          <circle cx="8.6" cy="12" r="5" {...p}/>
          <circle cx="15.4" cy="12" r="5" {...p}/>
          <path d="M12 8.3v7.4" {...p} strokeWidth="1.1" opacity=".7"/>
        </>)}
      {mark === "profile" && (<>
          <rect x="5" y="3.4" width="14" height="17.2" rx="2" {...p}/>
          <circle cx="12" cy="9.6" r="2.7" {...p}/>
          <path d="M8 16.6c.8-2.1 2.2-3.1 4-3.1s3.2 1 4 3.1" {...p}/>
        </>)}
      {mark === "reviews" && (<path d="M12 3.8l2.45 5 5.5.8-3.98 3.88.94 5.48L12 16.36l-4.91 2.6.94-5.48L4.05 9.6l5.5-.8z" {...p}/>)}
    </svg>);
}
/** v1.01: the main call to action, shiny and sparkling so it stands out -
 *  a gold button with a sweeping sheen and three twinkling sparkles. */
function ShineButton({ onClick, children }) {
    return (<button type="button" className="ff-btn ff-shine" onClick={onClick}>
      <i className="sp s1" aria-hidden="true"/>
      <i className="sp s2" aria-hidden="true"/>
      <i className="sp s3" aria-hidden="true"/>
      <span className="lab">{children}</span>
    </button>);
}
/** Marks a preview inert: it's a picture of a real card, not something to use. */
function InertBox({ className, children }) {
    const r = useRef(null);
    useEffect(() => {
        r.current?.setAttribute("inert", "");
    }, []);
    return <div ref={r} className={className} aria-hidden="true">{children}</div>;
}

