function DiscoverFireFlair({ kind = "team" }) {
  const nav = useHomeNav();
  const hire = useHireNav();
  const set = kind === "staff" ? DISCOVER_STAFF : kind === "party" ? DISCOVER_PARTY : DISCOVER;
  const [open, setOpen] = useState(null);
  const row = useRef(null);
  const go = (to) => {
    setOpen(null);
    setTimeout(() => {
      if (to === "profile") (kind === "team" ? nav.goProfile() : hire.toProfile());
      else if (to === "network") (kind === "team" ? nav.goNetwork() : hire.toNetwork(""));
      else if (to === "event") hire.toEvent();
      else scrollToSection(to.slice(1));
    }, 60);
  };
  const by = (dx) => { const el = row.current; if (el) el.scrollBy({ left: dx * Math.max(160, el.clientWidth * 0.8), behavior: "smooth" }); };
  const c = set.find(x => x.k === open);
  return (
    <section className="ff-sect ff-disc" id="ff-discover" aria-labelledby="ff-disc-h">
      <div className="ff-disc-head">
        <h2 id="ff-disc-h" className="ff-h1">Discover FireFlair</h2>
        <span className="ff-disc-arrows">
          <button type="button" onClick={() => by(-1)} aria-label="Scroll back"><DI.ChevronLeft size={18} /></button>
          <button type="button" onClick={() => by(1)} aria-label="Scroll on"><DI.ChevronRight size={18} /></button>
        </span>
      </div>
      <div className="ff-disc-row" ref={row} role="list">
        {set.map(x => (
          <button key={x.k} type="button" role="listitem" className="ff-disc-card" onClick={() => setOpen(x.k)} aria-haspopup="dialog" aria-label={`${x.t}: ${x.s}`}>
            <span className="ph">{IMGS[x.img] ? <img src={IMGS[x.img]} alt="" loading="eager" draggable={false} /> : null}</span>
            <span className="tx"><b>{x.t}</b><small>{x.s}</small></span>
          </button>
        ))}
      </div>
      <Sheet open={!!c} onClose={() => setOpen(null)} title={c ? c.h : ""} center>
        {c && (<div className="ff-disc-modal">
          {IMGS[c.img] && <span className="ph"><img src={IMGS[c.img]} alt="" /></span>}
          <p className="lead">{c.lead}</p>
          {c.body.map((t, i) => <p key={i}>{t}</p>)}
          <div className="acts">
            <button type="button" className="ff-btn primary wide" onClick={() => go(c.cta[1])}>{c.cta[0]}</button>
            {c.cta2 && <button type="button" className="ff-btn ghost wide" onClick={() => go(c.cta2[1])}>{c.cta2[0]}</button>}
          </div>
        </div>)}
      </Sheet>
    </section>
  );
}

