/* ==== v1.1 homes: FF Staff and FF Party ======================================
   Built from the FF Team home (same sections, same coins between them), with
   every module rewritten for the people each site is for. A home page says
   how the service works, then links to where the booking starts. */
const Repeat11 = lucideIcon("Repeat"), Contact11 = lucideIcon("Contact"), CalDays11 = lucideIcon("CalendarDays"), Clip11 = lucideIcon("ClipboardList"),
  Popper11 = lucideIcon("PartyPopper"), Badge11 = lucideIcon("BadgeCheck"), Bot11 = lucideIcon("Bot");

function useHireNav() {
  const { state, dispatch } = useStore();
  const site = hireSiteOf(state);
  const tab = (t) => { dispatch({ type: "TAB", tab: t }); window.scrollTo(0, 0); };
  return {
    site,
    toEvent: () => {
      if (site.party) { dispatch({ type: "V11_SET", patch: { bkView: { mode: "new" } } }); tab("bookings"); return; }
      dispatch({ type: "V11_SET", patch: { bkView: { mode: "new", open: "event" } } }); tab("bookings");
    },
    toBookings: (view) => { dispatch({ type: "V11_SET", patch: { bkView: view || { tab: "events" } } }); tab("bookings"); },
    toNetwork: (q) => { dispatch({ type: "NET_QUERY", q: q || "" }); tab("network"); },
    toProfile: () => tab("profile"),
    view: (id) => { dispatch({ type: "VIEW", id }); window.scrollTo(0, 0); },
  };
}

