/* The Review Card from the FF Team home, with full names for a business. */
function ReviewCard11({ from, to, how, text, status }) {
  const nm = (p) => p.isCompany ? p.name : p.name.split(" ")[0];
  return (
    <article className="ff-rvcard" aria-label={`Example Review Card from ${from.name} to ${to.name}`}>
      <div className="ff-rvcard-ribbon"><Star size={11} fill="currentColor" /> Review Card</div>
      <span className="ff-rvcard-coin"><Coin size={34} tier="gold" /></span>
      <div className="ff-rvcard-who">
        <span className="p">
          {from.isCompany ? <span className="ff-rv11-co">{coInitials(from.name)}</span> : <Portrait src={from.photo} name={from.name} size={54} tier={from.tier} />}
          <b>{nm(from)}</b><small>{from.profession}</small>
        </span>
        <span className="arrow" aria-hidden="true"><ArrowRight size={18} /></span>
        <span className="p"><Portrait src={to.photo} name={to.name} size={54} tier={to.tier} /><b>{nm(to)}</b><small>{to.profession}</small></span>
      </div>
      <div className="ff-rvcard-kind">{from.isCompany ? "Booked together" : "Booked for a party"}</div>
      <div className="ff-rvcard-stars" aria-label="Five out of five">★★★★★</div>
      <div className="ff-rvcard-rows">
        <div><span>Booked {nm(to)} before?</span><b className="yes">{from.isCompany ? "Yes" : "No"}</b></div>
        <div><span>Book again?</span><b className="yes">Yes</b></div>
        <div><span>How is {nm(to)} to work with?</span><b className="yes">{how}</b></div>
      </div>
      <p className="ff-rvcard-quote">"{text}"</p>
      <div className="ff-rvcard-foot done"><Check size={14} strokeWidth={2.6} /> {status}</div>
    </article>
  );
}
