const DX_ALIAS = { "ff-career": "ff-booktiles", "ff-training": "ff-booktiles", "ff-nx-svc-h": "ff-coming", "ff-nx-ck-h": "ff-coming", "ff-nx-svc": "ff-coming", "ff-nx-ck": "ff-coming" };

function DiscoverHub11({ cats = DX_TEAM, kind = "team" }) {
  const hire = useHireNav();
  const home = useHomeNav();
  const goSite = useGoSite();
  const base = kind === "staff" ? "ff-staff" : kind === "party" ? "ff-party" : "ff-team";
  const slugs = (() => { const raw = cats.map(c => c.t.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")); const short = raw.map(x => x.replace(/^(our|your)-/, "")); return raw.map((x, i) => short.filter(y => y === short[i]).length > 1 ? x : short[i]); })();
  const fromUrl = () => { const parts = String(window.location.hash || "").replace(/^#\/?/, "").split("/"); if (parts[0] !== base) return null; const i = slugs.indexOf(parts[1]); return i < 0 ? null : cats[i].k; };
  const [open, setOpen] = useState(() => { if (window.__ffUrlRead) return null; window.__ffUrlRead = true; return fromUrl(); });
  const [shape, setShape] = useState(null);
  const well = useRef(null), root = useRef(null), bar = useRef(null), sent = useRef(null), panel = useRef(null);
  const [leaving, setLeaving] = useState(null);
  const openRef = useRef(open); openRef.current = open;
  const hRef = useRef(0);
  const shownK = open || leaving;
  const cur = cats.find(c => c.k === shownK) || null;
  const idx = cur ? cats.indexOf(cur) : -1;
  const next = cur ? cats[(idx + 1) % cats.length] : null;
  /* v17.3.81: each pillar has five photos (pool). The tile shows one and the pillar's cards show
     three others, so nothing repeats. Every visit starts one photo further on, and while no pillar
     is open the tiles crossfade to their next photo, one tile at a time. */
  const [rot17, setRot17] = useState(() => { const v = dxVisit17(); return cats.map(() => v); });
  const rotOf = (c) => { const i = cats.indexOf(c); return rot17[i] == null ? 0 : rot17[i]; };
  useEffect(() => {
    if (cur || prefersReducedMotion()) return;
    let n = 0;
    const t = setInterval(() => {
      if (document.hidden) return;
      const i = n++ % cats.length;
      setRot17(r => cats.map((c, j) => (r[j] == null ? 0 : r[j]) + (j === i ? 1 : 0)));
    }, 4500);
    return () => clearInterval(t);
  }, [cur, cats]);
  const topOf = () => {
    const tb = document.querySelector(".ff-topbar"); if (!tb) return 0;
    const p = getComputedStyle(tb).position;
    return p === "sticky" || p === "fixed" ? Math.round(tb.getBoundingClientRect().height) : 0;
  };
  const toTop = () => requestAnimationFrame(() => requestAnimationFrame(() => {
    const s = sent.current; if (!s) return;
    const y = s.getBoundingClientRect().top + window.scrollY - topOf() - 6;
    window.scrollTo({ top: Math.max(0, y), behavior: prefersReducedMotion() ? "auto" : "smooth" });
  }));
  const showTile = (k) => {
    const b = bar.current; if (!b || b.scrollWidth <= b.clientWidth + 2) return;
    const tl = b.querySelector(`[data-k="${k}"]`); if (!tl) return;
    const br = b.getBoundingClientRect(), tr = tl.getBoundingClientRect();
    const want = b.scrollLeft + (tr.left - br.left) - (b.clientWidth - tr.width) / 2;
    b.scrollTo({ left: Math.max(0, Math.min(b.scrollWidth - b.clientWidth, want)), behavior: prefersReducedMotion() ? "auto" : "smooth" });
  };
  const wantTop = useRef(false);
  const grab = () => { hRef.current = panel.current ? panel.current.offsetHeight : 0; };
  const collapse = () => { const o = openRef.current; if (!o) return; grab(); setLeaving(o); setOpen(null); };
  const pick = (k) => { if (open === k) { collapse(); return; } grab(); setLeaving(null); setOpen(k); showTile(k); };
  const api = useRef({}); api.current = { collapse, grab };
  const goNext = (k) => { wantTop.current = true; pick(k); };
  const close = () => { collapse(); };
  const jump = (id) => { const el = document.getElementById(id); if (el) el.scrollIntoView({ behavior: prefersReducedMotion() ? "auto" : "smooth", block: "start" }); };
  const run = (go) => {
    if (go[0] === "#") { jump(go.slice(1)); return; }
    if (go.indexOf("site:") === 0) { goSite(go.slice(5)); return; }
    if (go === "profile") { if (kind === "team") home.goProfile(); else hire.toProfile(); return; }
    if (go === "network") { hire.toNetwork(""); return; }
    if (go === "bookings") { hire.toBookings(); return; }
    if (go === "book") { hire.toEvent(); }
  };

  /* One outline for the open tile and its box: a single path, drawn from where they actually sit. */
  React.useLayoutEffect(() => {
    if (!cur) { setShape(null); return; }
    const calc = () => {
      const w = well.current, b = bar.current, p = panel.current; if (!w || !b || !p) return;
      const t = b.querySelector(`[data-k="${cur.k}"]`); if (!t) return;
      const wr = w.getBoundingClientRect(), pr = p.getBoundingClientRect(), tr = t.getBoundingClientRect();
      const px0 = pr.left - wr.left, px1 = pr.right - wr.left, py0 = pr.top - wr.top, py1 = pr.bottom - wr.top;
      const tx0 = Math.max(tr.left - wr.left, px0), tx1 = Math.min(tr.right - wr.left, px1), ty0 = tr.top - wr.top;
      const mob = window.innerWidth < 760;
      const R = mob ? 12 : 18, rt = mob ? 18 : 22, rc = mob ? 22 : 30, rp = 8;
      const gl = tx0 - px0, gr = px1 - tx1;
      const fL = gl < 3, fR = gr < 3, Rl = gl < 7 ? 0 : Math.min(R, gl), Rr = gr < 7 ? 0 : Math.min(R, gr);
      let d = `M${px0},${py1 - rc} `;
      if (fL) d += `L${px0},${ty0 + rt} A${rt},${rt} 0 0 1 ${px0 + rt},${ty0} `;
      else d += `L${px0},${py0 + rp} A${rp},${rp} 0 0 1 ${px0 + rp},${py0} L${tx0 - Rl},${py0} A${Rl},${Rl} 0 0 0 ${tx0},${py0 - Rl} L${tx0},${ty0 + rt} A${rt},${rt} 0 0 1 ${tx0 + rt},${ty0} `;
      d += `L${tx1 - rt},${ty0} `;
      if (fR) d += `A${rt},${rt} 0 0 1 ${px1},${ty0 + rt} L${px1},${py1 - rc} `;
      else d += `A${rt},${rt} 0 0 1 ${tx1},${ty0 + rt} L${tx1},${py0 - Rr} A${Rr},${Rr} 0 0 0 ${tx1 + Rr},${py0} L${px1 - rp},${py0} A${rp},${rp} 0 0 1 ${px1},${py0 + rp} L${px1},${py1 - rc} `;
      d += `A${rc},${rc} 0 0 1 ${px1 - rc},${py1} L${px0 + rc},${py1} A${rc},${rc} 0 0 1 ${px0},${py1 - rc} Z`;
      const fills = [];
      if (!fL && Rl > 5) fills.push(`M${tx0 - Rl},${py0} A${Rl},${Rl} 0 0 0 ${tx0},${py0 - Rl} L${tx0},${py0} Z`);
      if (!fR && Rr > 5) fills.push(`M${tx1},${py0 - Rr} A${Rr},${Rr} 0 0 0 ${tx1 + Rr},${py0} L${tx1},${py0} Z`);
      setShape({ w: Math.round(wr.width), h: Math.round(wr.height), d, fills, tx: Math.round(tx0 - px0), tw: Math.round(tx1 - tx0), tr: Math.round(Math.max(0, gr)) });
    };
    calc();
    const b = bar.current, ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(calc) : null;
    if (ro) { ro.observe(panel.current); ro.observe(well.current); }
    window.addEventListener("resize", calc);
    if (b) b.addEventListener("scroll", calc, { passive: true });
    return () => { if (ro) ro.disconnect(); window.removeEventListener("resize", calc); if (b) b.removeEventListener("scroll", calc); };
  }, [shownK]);

  /* The panel grows and shrinks, so everything below it is pushed down (or pulled back up) instead of jumping. */
  React.useLayoutEffect(() => {
    const p = panel.current; if (!p) return;
    const clear = () => { p.style.height = ""; p.style.overflow = ""; p.style.transition = ""; p.style.paddingTop = ""; p.style.paddingBottom = ""; };
    if (open) {
      const natural = p.offsetHeight, from = hRef.current; hRef.current = 0;
      if (prefersReducedMotion() || Math.abs(from - natural) < 2) { clear(); return; }
      p.style.overflow = "hidden"; p.style.height = from + "px";
      if (!from) { p.style.paddingTop = "0px"; p.style.paddingBottom = "0px"; }
      void p.offsetHeight;
      p.style.transition = "height .55s cubic-bezier(.22,.8,.24,1), padding .55s cubic-bezier(.22,.8,.24,1)";
      p.style.height = natural + "px"; p.style.paddingTop = ""; p.style.paddingBottom = "";
      const t = setTimeout(clear, 600);
      return () => clearTimeout(t);
    }
    if (leaving) {
      if (prefersReducedMotion()) { setLeaving(null); return; }
      const from = p.offsetHeight;
      p.style.overflow = "hidden"; p.style.height = from + "px"; void p.offsetHeight;
      p.style.transition = "height .45s cubic-bezier(.4,0,.2,1), padding .45s cubic-bezier(.4,0,.2,1)";
      p.style.height = "0px"; p.style.paddingTop = "0px"; p.style.paddingBottom = "0px";
      const t = setTimeout(() => setLeaving(null), 480);
      return () => clearTimeout(t);
    }
  }, [open, leaving]);

  /* "Next" starts the new pillar at the top, where people begin reading. */
  React.useLayoutEffect(() => {
    if (!wantTop.current) return;
    wantTop.current = false;
    const go = () => { const r = root.current; if (!r) return; window.scrollTo({ top: Math.max(0, r.getBoundingClientRect().top + window.scrollY - topOf() - 8), behavior: "auto" }); };
    go(); requestAnimationFrame(go); setTimeout(go, 120);
  }, [open]);

  /* The address follows the open pillar (ff-team/community, ff-party/booking ...); the Home tab collapses it. */
  const seen = useRef(false);
  useEffect(() => {
    if (!seen.current) { seen.current = true; if (!open) return; }
    const path = open ? `${base}/${slugs[cats.findIndex(c => c.k === open)]}` : base;
    try { const u = "#/" + path; if (window.location.hash !== u) window.history.pushState({ ff: path }, "", u); } catch (e) { try { window.location.hash = "/" + path; } catch (_) {} }
  }, [open]);
  useEffect(() => {
    const sync = () => { const k = fromUrl(); if (k === openRef.current) return; if (!k) { api.current.collapse(); return; } api.current.grab(); setLeaving(null); setOpen(k); };
    window.addEventListener("popstate", sync); window.addEventListener("hashchange", sync);
    const home = (e) => {
      const b = e.target && e.target.closest ? e.target.closest(".ff-bottomnav button, .ff-desknav button") : null; if (!b) return;
      if ((b.getAttribute("aria-label") || b.textContent || "").trim() !== "Home") return;
      api.current.collapse(); window.scrollTo({ top: 0, behavior: "auto" });
    };
    document.addEventListener("click", home, true);
    return () => { window.removeEventListener("popstate", sync); window.removeEventListener("hashchange", sync); document.removeEventListener("click", home, true);
      try { if (String(window.location.hash).indexOf("#/" + base + "/") === 0) window.history.replaceState(null, "", "#/" + base); } catch (_) {} };
  }, []);

  /* Remember how far below the top bar the sections should land. */
  useEffect(() => { if (root.current) root.current.style.setProperty("--dx-top", topOf() + "px"); }, [open]);

  /* Links to a section inside a closed panel open that panel first. */
  useEffect(() => {
    window.__ffDxReveal = (id) => {
      const pid = DX_ALIAS[id] || id;
      const c = cats.find(x => x.parts.some(p => p.id === pid));
      if (!c) return false;
      if (open === c.k && document.getElementById(id)) return false;
      grab(); setLeaving(null); setOpen(c.k);
      setTimeout(() => { const el = document.getElementById(id) || document.getElementById(pid); if (el) el.scrollIntoView({ behavior: prefersReducedMotion() ? "auto" : "smooth", block: "start" }); }, 420);
      return true;
    };
    return () => { delete window.__ffDxReveal; };
  }, [open, cats]);

  const Ic = cur ? cur.icon : null;
  return (
    <section className={`ff-sect ff-dx${cur ? " is-open" : ""}`} id="ff-discover" aria-labelledby="ff-dx-h" ref={root}>
      <style>{ROT17_CSS}</style>
      <h2 id="ff-dx-h" className="ff-h1 ff-dx-h">Discover FireFlair</h2>
      <span className="ff-dx-sent" ref={sent} aria-hidden="true" />
      <div className="ff-dx-well" ref={well}>
      <div className="ff-dx-bar" ref={bar}>
        {cats.map(c => { const on = shownK === c.k; return (
          <button key={c.k} type="button" data-k={c.k} className={`ff-dx-tile${on ? " on" : ""}`} aria-expanded={on} aria-controls="ff-dx-panel" onClick={() => pick(c.k)}>
            <DxPh17 c={c} n={rotOf(c)} />
            <span className="chev" aria-hidden="true"><DX_I.ChevronDown size={14} strokeWidth={2.4} /></span>
            <span className="tx"><b>{c.t}</b><small>{c.s}</small></span>
          </button>); })}
      </div>

      {cur && (
        <div id="ff-dx-panel" ref={panel} className="ff-dx-panel" role="region" aria-label={cur.t} style={shape ? { "--tx": `${shape.tx}px`, "--tw": `${shape.tw}px`, "--tr": `${shape.tr}px` } : undefined}>
          <div className="ff-dx-intro" key={"b" + cur.k}>
            <h3>{cur.h}</h3>
            {cur.p.map((t, n) => <p key={n}>{t}</p>)}
          </div>
          {cur.jn && (<>
            <ol className="ff-cta17" aria-label={`${cur.t}: three ways in`}>
              {cur.jn.map((j, i) => { const ik = cur.pool ? dxCard17(cur, rotOf(cur), i) : [cur.img, ...cats.filter(c => c !== cur).map(c => c.img)][i]; return (
                <li key={j.t}>
                  <span className="ph">{IMGS[ik] ? <img src={IMGS[ik]} style={fp17(ik)} alt="" draggable={false} /> : null}<i>{i + 1}</i></span>
                  <b>{j.t}</b>
                  <span className="t">{j.x}</span>
                  <button type="button" onClick={() => run(j.go)}>{j.b}</button>
                </li>); })}
            </ol>
            <CoinDivider />
          </>)}
          <div className="ff-dx-body" key={cur.k}>
            {cur.parts.map((p, i) => <React.Fragment key={p.id}>{i > 0 && <CoinDivider />}{p.r()}</React.Fragment>)}
          </div>
          <div className="ff-dx-foot">
            <button type="button" className="ff-dx-next" onClick={() => goNext(next.k)}>
              <span className="ph">{IMGS[dxCard17(next, rotOf(next), 0)] ? <img src={IMGS[dxCard17(next, rotOf(next), 0)]} style={fp17(dxCard17(next, rotOf(next), 0))} alt="" draggable={false} /> : null}</span>
              <span className="tx"><small>Next</small><b>{next.t}</b></span><DX_I.ArrowRight size={20} />
            </button>
            <button type="button" className="ff-dx-close" onClick={close}><DX_I.ChevronUp size={16} /> Close {cur.t}</button>
          </div>
        </div>
      )}
      {cur && shape && (
        <svg className="ff-dx-svg" width={shape.w} height={shape.h} viewBox={`0 0 ${shape.w} ${shape.h}`} aria-hidden="true" focusable="false">
          {shape.fills.map((p, n) => <path key={n} d={p} className="fl" />)}
          <path d={shape.d} className="ln" />
        </svg>
      )}
      </div>
    </section>
  );
}

